INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0622', 'spa', 'Destruir, arruinar; perder; en voz media/intransitivo, perecer, arruinarse o perderse', 'Un verbo de gran fuerza que abarca la destrucción total, la ruina y la pérdida, presente en algunos de los pasajes más dramáticos del Nuevo Testamento. En su uso transitivo describe a reyes que buscan destruir (Mt 2:13), autoridades que conspiran para matar (Mt 12:14) y un señor que destruirá sin misericordia a los labradores malvados (Mt 21:41). En su voz media intransitiva, capta el clamor de los discípulos aterrados: «¡perecemos!» (Mt 8:25), y la advertencia solemne de que quien se aferre a su vida la perderá (Mt 16:25). La forma participial genera la tierna categoría de «lo perdido»: la oveja perdida, la moneda perdida, el hijo perdido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0625', 'spa', 'Apolos — Cristiano judío alejandrino, predicador elocuente y asociado de Pablo en la iglesia primitiva. El nombre propio Ἀπολλῶς (Apolos) identifica a', 'Apolos — Cristiano judío alejandrino, predicador elocuente y asociado de Pablo en la iglesia primitiva. El nombre propio Ἀπολλῶς (Apolos) identifica a un judío alejandrino descrito como ''elocuente'' y ''poderoso en las Escrituras'' (Hch 18:24). Después de que Priscila y Aquila lo instruyeran con mayor exactitud en el Camino, Apolos se convirtió en un predicador influyente en Acaya y Corinto. Su prominencia alimentó involuntariamente las divisiones partidistas (''Yo sigo a Apolos'', 1 Co 1:12; 3:4), las cuales Pablo abordó insistiendo en que él y Apolos eran simplemente servidores por medio de quienes Dios obraba (1 Co 3:5-6). Pablo luego instó a Apolos a visitar Corinto de nuevo (1 Co 16:12) y lo encomendó a Tito (Tit 3:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0626', 'spa', 'Hacer una defensa, hablar en defensa propia — ofrecer una defensa verbal contra acusaciones, especialmente en contextos legales. El verbo ἀπολογέομαι ', 'Hacer una defensa, hablar en defensa propia — ofrecer una defensa verbal contra acusaciones, especialmente en contextos legales. El verbo ἀπολογέομαι (apologeomai) significa ''hacer una defensa'' o ''hablar en defensa propia'', típicamente en un contexto judicial o cuasi-judicial. Jesús instruye a sus discípulos a no preocuparse por cómo se defenderán ante las autoridades (Lc 12:11; 21:14). El término domina los relatos del juicio de Pablo: se defiende ante Félix (Hch 24:10), Festo (Hch 25:8; 26:1-2, 24) e implícitamente ante el tribunal romano (2 Ti 4:16). Romanos 2:15 extiende la imagen al diálogo moral interior donde los pensamientos ''acusan o defienden''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0627', 'spa', 'Defensa verbal o justificacion razonada; discurso en respuesta a acusaciones, no una expresion de arrepentimiento.', 'Del griego ἀπό (de, desde) + λόγος (palabra, razon), apologia designa una defensa verbal razonada que se ofrece en respuesta a cargos o criticas. No debe confundirse con el sentido moderno de ''disculpa'' como expresion de arrepentimiento. Pablo la emplea para sus discursos formales de defensa (Hch 22:1; Fil 1:7, 16), y el termino aparece en la exhortacion a estar siempre preparados para presentar una ''defensa'' de la esperanza que hay en nosotros (1 Pe 3:15). En 2 Corintios 7:11, la apologia de los corintios demuestra su ferviente deseo de vindicarse. El castellano ''defensa'' conserva fielmente el matiz legal-forense del termino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0628', 'spa', 'lavar, limpiar mediante el lavado', 'Verbo compuesto que significa lavar o quitar completamente mediante el lavado. En Hechos 22:16, Ananías manda a Saulo lavar sus pecados mediante el bautismo. En 1 Corintios 6:11, Pablo recuerda a los corintios que fueron lavados de su estado pecaminoso anterior. Homero lo usaba para lavar sangre o salitre del cuerpo; el Nuevo Testamento aplica esta limpieza física metafóricamente a la purificación espiritual. La voz media enfatiza lavarse a sí mismo o hacerse lavar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0629', 'spa', 'Redención, liberación mediante el pago de un rescate; la liberación lograda por la obra expiatoria de Cristo. Sustantivo abstracto que designa la libe', 'Redención, liberación mediante el pago de un rescate; la liberación lograda por la obra expiatoria de Cristo. Sustantivo abstracto que designa la liberación obtenida mediante el pago de un precio de rescate. En el Nuevo Testamento funciona casi exclusivamente como término teológico para la liberación consumada por la muerte sacrificial de Cristo (Ro 3:24; Ef 1:7, 14; Col 1:14; Heb 9:15). Lucas 21:28 extiende el concepto a la liberación escatológica en el regreso de Cristo. Las traducciones multilingües convergen en la idea de rescate-liberación: español ''redención'', hindi ''छुटकारा'' (liberación), árabe ''الفِداء'' (rescate), coreano ''구속'' (redención) y suajili ''ukombozi'' (liberación).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0630', 'spa', 'Soltar, despedir, repudiar o perdonar; liberar cautivos, dispersar multitudes, divorciarse, absolver pecados', 'Ἀπολύω pertenece a la familia de compuestos de λύω («desatar») y porta la imagen fundamental de soltar o dejar ir. En los Evangelios opera en cuatro esferas sociales distintas: la judicial (soltar a Barrabás), la comunitaria (despedir a las multitudes tras los milagros de alimentación), la doméstica (los debates sobre el divorcio en Mt 5 y 19) y la espiritual (perdonar pecados en Lc 6:37). La evidencia multilingüe confirma fronteras conceptuales reales: el árabe asigna raíces completamente diferentes para cada sentido, y el coreano y el suajili despliegan igualmente elementos léxicos distintos en los cuatro dominios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0635', 'spa', 'extraviar, hacer que alguien se desvíe de la verdad o del camino correcto', 'Verbo que describe el acto de hacer que alguien se desvíe o sea engañado. Jesús advierte en Marcos 13:22 que falsos mesías intentarán extraviar incluso a los elegidos. Pablo en 1 Timoteo 6:10 describe cómo el amor al dinero ha desviado a algunos creyentes de la fe. El uso clásico incluye tanto el vagabundeo físico como la digresión intelectual de la verdad. El compuesto enfatiza la noción de desviarse de una posición o creencia apropiada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0636', 'spa', 'zarpar, navegar, hacerse a la vela; partir por mar', 'Verbo marítimo que significa zarpar o partir por mar, empleado exclusivamente en Hechos para narrar los viajes misioneros de Pablo. La palabra señala transiciones entre campos de misión: zarpando de Seleucia (Hch 13:4), partiendo de Atalia tras el primer viaje (Hch 14:26), costeando más allá de Éfeso (Hch 20:15) y embarcándose rumbo a Italia (Hch 27:1). Cada aparición marca un giro geográfico decisivo en la misión apostólica, subrayando el carácter itinerante de la evangelización paulina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0637', 'spa', 'lavar a fondo, limpiar completamente mediante lavado, enjuagar por completo', 'Verbo compuesto que denota un lavado o limpieza exhaustiva. El prefijo intensifica la acción básica de lavar para indicar que se realiza de manera completa: lavar algo a fondo o eliminarlo por completo mediante el agua. En el uso homérico, el mar arrastra restos o hebras. El verbo puede describir la acción física de limpiar algo lavándolo o, en sentido más abstracto, la eliminación total de algo a través del lavado. El compuesto sugiere no una limpieza superficial, sino una ablución completa y profunda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0638', 'spa', 'ahogar, asfixiar o anegar', 'Verbo vívido que describe la asfixia o ahogamiento. Ambas apariciones en el Nuevo Testamento están en el relato de Lucas de la parábola del sembrador, donde espinas ahogan la semilla que crece (Lucas 8:7) y demonios impulsan una manada de cerdos a ahogarse en un lago (8:33). El griego clásico lo empleaba para estrangular, atragantarse con comida, o ahogarse. El prefijo intensifica el significado básico de estrangular hasta la asfixia completa o muerte por ahogo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0639', 'spa', 'Estar perplejo, desconcertado o sin saber qué hacer; estado de incertidumbre mental sobre qué pensar o cómo actuar.', 'ἀπορέω capta un matiz particular de confusión: no la mera ignorancia, sino la frustrante experiencia de no encontrar salida ni respuesta clara. Aparece en momentos de crisis psicológica en el NT: Herodes queda ''muy perplejo'' ante Juan el Bautista (Mr 6:20), las mujeres en la tumba vacía permanecen desconcertadas (Lc 24:4), los discípulos se miran con incertidumbre (Jn 13:22) y Festo confiesa su desconcierto ante disputas judías (Hch 25:20). Pablo lo emplea memorablemente: ''perplejos, pero no desesperados'' (2 Co 4:8), distinguiendo el desconcierto pasajero de la desesperanza definitiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0645', 'spa', 'arrancar, apartar con fuerza, separar; retirar(se) violenta o emocionalmente', 'Con la fuerza de un desgarro violento o una separación forzada, este verbo abarca rupturas tanto físicas como relacionales. Pedro desenvainó su espada y cortó la oreja del siervo (Mat 26:51). Jesús se apartó de los discípulos como a un tiro de piedra para orar (Luc 22:41). Pablo advierte que de entre los ancianos de Éfeso algunos se levantarán arrastrando discípulos tras de sí (Hch 20:30). La dolorosa despedida en Mileto, donde los creyentes fueron «arrancados» unos de otros (Hch 21:1), añade una profunda dimensión emocional al verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0646', 'spa', 'apostasía, rebelión contra Dios, abandono de la fe', 'Término técnico religioso que denota el abandono formal de la fe o rebelión contra Dios. En Hechos 21:21, Pablo es falsamente acusado de enseñar a los judíos a apostatar de Moisés. En 2 Tesalonicenses 2:3, Pablo advierte que el día del Señor no vendrá hasta que ocurra ''la apostasía''. Aunque el griego clásico lo usaba ampliamente para rebelión política o partida física, el uso bíblico lo limita a defección religiosa. La Septuaginta ya lo empleaba para rebelión contra Dios, estableciendo su peso teológico antes del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0647', 'spa', 'Carta de divorcio, documento legal de disolución matrimonial', 'Esta expresión sustantiva (literalmente «de repudio») se refiere al documento legal escrito que disuelve oficialmente un matrimonio. Jesús hace referencia a la disposición mosaica que permitía al hombre entregar a su esposa una «carta de divorcio» y despedirla (Mateo 5:31; 19:7; Marcos 10:4). El término aparece en discusiones sobre la licitud y los límites del divorcio bajo la ley. Representa la dimensión formal y jurídica de la separación conyugal, en contraste con la enseñanza de Jesús sobre el propósito original de Dios para el matrimonio. La «carta» hacía oficial el divorcio y protegía los derechos de la mujer repudiada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0649', 'spa', 'Enviar en misión o comisión; despachar un representante autorizado, mensajero o agente; en pasiva, ser enviado', 'Ἀποστέλλω es el verbo detrás del sustantivo ἀπόστολος (''apóstol''), y conlleva un peso que un simple ''enviar'' no puede transmitir. A diferencia del más general πέμπω, ἀποστέλλω implica autorización: el enviado va con la autoridad y el propósito del que envía. Cuando Jesús ''envía'' a los Doce (Mt 10:5), o cuando el Padre ''envía'' al Hijo (Jn 5:36), el verbo enmarca el acto como comisionamiento, no como mero despacho. El español enviar, el alemán senden y el francés envoyer traducen tanto πέμπω como ἀποστέλλω, pero el patrón de uso neotestamentario reserva consistentemente ἀποστέλλω para momentos de misión deliberada y delegada. El raro sentido de despedir en Mc 5:10 y 12:3 conserva el significado clásico más antiguo de alejar de la propia presencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0650', 'spa', 'Defraudar, privar o robar a alguien lo que legítimamente le pertenece; retener injustamente.', 'ἀποστερέω designa el acto de robar, defraudar o privar a alguien de lo que se le debe. Aparece cuando Jesús dice al joven rico ''no defraudes'' (Mr 10:19), en la reprensión de Pablo a los corintios que se estafan en pleitos (1 Co 6:7-8) y en su consejo de que los cónyuges no se priven el uno del otro (1 Co 7:5). El término conlleva una fuerte carga ética: no es simple pérdida, sino apropiación injusta, violación de la confianza o la obligación debida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0651', 'spa', 'apostolado; el oficio, comisión o ministerio de ser enviado como representante autorizado', 'Derivado de ἀποστέλλω (''enviar''), ἀποστολή designa el oficio y la comisión de quien es enviado con plena autoridad en nombre de otro. En sus cuatro apariciones neotestamentarias se refiere exclusivamente al ministerio apostólico: la misión divinamente autorizada confiada a los Doce y a Pablo. En Hechos 1:25 nombra el cargo vacante por la traición de Judas; en Romanos 1:5 y Gálatas 2:8, Pablo habla del apostolado que recibió por gracia; y en 1 Corintios 9:2, los propios corintios son el «sello» de su apostolado. El término subraya el carácter institucional y de oficio de la misión apostólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0652', 'spa', 'Apóstol, enviado con autoridad; mensajero comisionado o emisario, especialmente de Cristo', 'El griego ἀπόστολος designa a alguien enviado con plena autoridad para representar al que lo envía, un concepto más rico que el de simple «mensajero». En el Nuevo Testamento identifica sobre todo a los Doce elegidos por Jesús (Lc 6:13) y a Pablo, quien defiende vigorosamente su comisión apostólica (Gá 1:1). Más allá de este círculo íntimo, el término se extiende a delegados eclesiales como Bernabé y posiblemente Andrónico y Junia. El trasfondo clásico de despacho naval y misión embajadora enriquece la carga teológica: un apóstol lleva todo el peso de aquel que lo envió. El español «apóstol», el francés apôtre y el alemán Apostel transliteran en lugar de traducir, reflejando el estatus único de esta palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0654', 'spa', 'Apartarse, rechazar o devolver; abarca desde la apostasia personal y la remocion del pecado hasta el extraviar a otros y restituir fisicamente un objeto.', 'Construido sobre la raiz στρέφω (''girar'') con el prefijo ἀπο- (''lejos de''), este verbo cubre un amplio campo semantico unificado por la idea de inversion direccional. La mayoria de los usos neotestamentarios describen a personas que se apartan de la verdad, de sus lideres o de la sana doctrina (2 Ti 1:15; 4:4; Tit 1:14). Pablo y Pedro tambien lo aplican a la obra redentora de Dios al apartar la impiedad (Ro 11:26; Hch 3:26). Un caso describe subversion politica (Lc 23:14), y otro retorna al sentido concreto y fisico cuando Jesus ordena a Pedro que devuelva su espada a su lugar (Mt 26:52). Las traducciones al castellano reflejan bien esta variedad: ''apartaran'' para la desercion doctrinal, ''apartara'' para la remocion divina del pecado, ''pervirtiendo'' para el extraviar, y ''Vuelve'' para la restitucion fisica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0656', 'spa', 'Expulsado de la sinagoga, excomulgado de la comunidad de culto judía', 'Este adjetivo, exclusivo del Evangelio de Juan, describe a quienes eran excluidos de la comunión sinagogal. Los judíos habían acordado que quien confesara a Jesús como Mesías sería «expulsado de la sinagoga» (Juan 9:22; 12:42). Jesús advierte a sus discípulos que serán «expulsados de las sinagogas», e incluso que quienes los maten creerán ofrecer un servicio a Dios (16:2). El término representa la excomunión formal de la comunidad del pacto, un castigo social y religioso devastador en el judaísmo del siglo primero. Captura el alto costo de seguir a Jesús en aquel contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0657', 'spa', 'Despedirse de alguien o decir adiós; por extensión, renunciar a las posesiones o apegos. Verbo de separación — de personas o de cosas.', 'Primariamente un verbo de despedida. Pablo se despide de los hermanos repetidamente durante sus viajes misioneros (Hechos 18:18, 18:21; 2 Corintios 2:13), y en Marcos 6:46 Jesús se despide de la multitud antes de retirarse a orar. Pero en Lucas 14:33, Jesús extiende la metáfora de manera sorprendente: así como uno se despide de una persona, el discípulo debe ''despedirse'' de todas sus posesiones, renunciando a ellas por completo. Lucas 9:61 se sitúa en la bisagra entre estos dos sentidos, donde un aspirante a seguidor pide ir a despedirse de los de su casa, pero la respuesta de Jesús implica que el verdadero discipulado es una despedida sin retorno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0658', 'spa', 'completar, cumplir, llevar a pleno cumplimiento', 'Verbo que significa llevar a término o cumplir plenamente. Jesús en Lucas 13:32 habla de completar su obra al tercer día. Santiago 1:15 describe cómo el pecado, cuando madura completamente, da a luz la muerte. El uso clásico enfatiza terminar lo iniciado, pagar lo debido, o producir un resultado final. El compuesto sugiere terminación exhaustiva, llevando algo desde el principio hasta el fin completo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0659', 'spa', 'Despojarse o dejar a un lado, ya sea figuradamente (conductas pecaminosas, el viejo hombre) o literalmente (depositar objetos en un lugar).', 'Un verbo rico en matiz de remocion, empleado con mayor frecuencia en el Nuevo Testamento como vivida metafora de transformacion moral. Se exhorta a los creyentes a ''despojarse'' del viejo hombre como quien se quita ropa gastada (Ef 4:22; Col 3:8), a dejar a un lado todo peso y el pecado que nos asedia (He 12:1), y a desechar toda inmundicia (Stg 1:21). Los terminos castellanos ''despojar'' y ''desechar'' transmiten poderosamente esta imagen de quitar y apartar. En su sentido literal, menos frecuente, el verbo describe el depositar algo fisicamente: los testigos pusieron sus vestiduras a los pies de Saulo (Hch 7:58), y Herodes puso a Juan en prision (Mt 14:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0660', 'spa', 'sacudir, sacudirse de encima', 'Verbo gestual vívido que describe el acto de sacudir algo del propio cuerpo. Jesús instruye a sus discípulos a sacudir el polvo de sus pies como testimonio contra las ciudades que los rechacen (Lucas 9:5). Pablo sacude una víbora de su mano al fuego en Malta (Hechos 28:5). La voz media enfatiza acción personal: sacudirse algo de uno mismo. Los autores clásicos lo usaban para librarse de cargas o cosas no deseadas, incluyendo metafóricas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0663', 'spa', 'severidad, rigor, dureza en el trato', 'Sustantivo que denota severidad o rigor. Pablo lo usa dos veces en Romanos 11:22 en una estructura quiástica contrastando la bondad y severidad de Dios: severidad hacia los que cayeron, bondad hacia los que permanecen en su bondad. El término lleva connotaciones de decisión cortante, derivado de la raíz que significa cortar afiladamente. El uso clásico incluía trato duro, leyes estrictas, o incluso tortura. El uso de Pablo enfatiza el juicio inflexible de Dios junto con su misericordia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0664', 'spa', 'severamente, con dureza, con rigor cortante', 'Adverbio que significa severamente o con dureza. Pablo lo usa dos veces para describir cómo podría ejercer autoridad apostólica: con rigor en 2 Corintios 13:10 y mandando a Tito reprender a los cretenses severamente (Tito 1:13). El término deriva de la misma raíz que ''severidad'' (G0663), llevando connotaciones de decisión cortante. Describe el tono y modo de reprensión o corrección que es directo e implacable en lugar de suave.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0667', 'spa', 'Llevar, transportar o conducir de un lugar a otro; se usa tanto de traslados físicos como de transporte visionario.', 'ἀποφέρω significa llevar o transportar algo o a alguien de un lugar a otro. El término abarca un abanico sorprendentemente amplio de movimientos en el NT: el concilio llevando a Jesús ante Pilato (Marcos 15:1), los ángeles transportando a Lázaro al seno de Abraham (Lucas 16:22), los paños de sanidad llevados desde el cuerpo de Pablo a los enfermos (Hechos 19:12), y la ofrenda siendo enviada a Jerusalén (1 Corintios 16:3). De manera más vívida, el Espíritu ''lleva'' a Juan en un transporte visionario para contemplar a Babilonia y la Nueva Jerusalén (Apocalipsis 17:3; 21:10). Ya sea físico, angélico o espiritual, el hilo conductor es la transferencia de un lugar a otro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0668', 'spa', 'Escapar, huir de, librarse del peligro o de la corrupción', 'Este verbo significa huir de algo peligroso o dañino y lograr escapar con éxito. Pedro lo emplea tres veces en su segunda epístola en el contexto de escapar de la corrupción mundana. Los creyentes han escapado de la contaminación del mundo mediante el conocimiento de Cristo (2 Pedro 1:4). Los falsos maestros seducen a quienes apenas están «escapando» del error (2:18). Lo más trágico es que algunos que escaparon de la contaminación vuelven a enredarse, haciendo que su estado final sea peor (2:20). El término enfatiza la huida exitosa del peligro, aunque esa libertad puede perderse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0669', 'spa', 'Proclamar, pronunciar, declarar; dar voz a algo con autoridad o inspiración', 'Este verbo significa hablar o pronunciar con fuerza, a menudo con connotaciones de discurso autoritativo o inspirado. En Pentecostés, los creyentes llenos del Espíritu comenzaron a «proclamar» en otras lenguas según el Espíritu les daba que hablasen (Hechos 2:4). Pedro «declaró» al pueblo reunido en Jerusalén, dirigiéndose a ellos con denuedo (2:14). Pablo protesta ante Festo que no está loco, sino que «pronuncia» palabras de verdad y cordura (26:25). El trasfondo clásico de pronunciar apotegmas (sentencias memorables) aporta el matiz de un discurso solemne y significativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0672', 'spa', 'Partir, retirarse, alejarse de un lugar o persona; irse, apartarse', 'Este verbo expresa la acción de partir o retirarse de un lugar o de la presencia de alguien. Jesús ordena a los obradores de maldad que se aparten de él (Mt 7:23). Un espíritu inmundo sacude violentamente a un muchacho y apenas se aparta de él (Lc 9:39). Pablo y sus compañeros partieron de Perga después de que Juan Marcos los dejara (Hch 13:13). La palabra subraya el acto de separarse, ya sea por mandato, de forma voluntaria o, en el caso del demonio, de manera forzada. Puede conllevar matices de separación definitiva o cese de presencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0673', 'spa', 'separar, apartarse de, ser dividido de', 'Verbo que describe separación o división. En Hechos 15:39, describe el desacuerdo agudo que separó a Pablo y Bernabé. En Apocalipsis 6:14, el cielo se parte y se separa como un rollo que se enrolla. La voz pasiva indica ser separado por fuerzas o circunstancias externas. El uso clásico incluía separar el trigo de la paja, apartar cosas en categorías, o vomitar (separación forzosa).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0677', 'spa', 'Irreprochable, sin ofensa, que no causa tropiezo a otros', 'Este adjetivo describe a quien no causa ofensa ni tropiezo a los demás. Pablo se esfuerza por mantener una conciencia «sin ofensa» ante Dios y ante los hombres (Hch 24:16). Instruye a los creyentes a vivir «sin dar tropiezo» a judíos, griegos ni a la iglesia de Dios (1 Co 10:32). En Filipenses 1:10, Pablo ora para que los creyentes sean «irreprochables» hasta el día de Cristo. El término compuesto sugiere tanto no tropezar uno mismo como no hacer tropezar a otros, representando una integridad ética que evita crear obstáculos para la fe ajena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0680', 'spa', 'El verbo griego ἅπτομαι (voz media de ἅπτω, ''sujetar, encender'') en su uso neotestamentario se centra casi por completo en el contacto físico, y espec', 'El verbo griego ἅπτομαι (voz media de ἅπτω, ''sujetar, encender'') en su uso neotestamentario se centra casi por completo en el contacto físico, y especialmente en el poder extraordinario que se transmitía al tocar a Jesús. En 30 de sus 36 apariciones, ἅπτομαι describe el toque sanador: el leproso a quien Jesús tocó (Mateo 8:3), la mujer con hemorragia que asió su manto (Mateo 9:20-21), las multitudes que se apretaban para tocarlo (Marcos 6:56). Un pequeño grupo de pasajes (4 apariciones) invierte el toque en prohibición: ''No te aferres a mí'' (Juan 20:17), la pregunta retórica de Pablo ''es bueno no tocar mujer'' (1 Corintios 7:1) y las reglas ascéticas ''no manejes, no gustes, no toques'' (Colosenses 2:21). Un último par de versículos emplea ἅπτομαι para el contacto amenazante o maligno: el maligno ''no lo toca'' al nacido de Dios (1 Juan 5:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0681', 'spa', 'Encender, prender fuego o luz a una lámpara o fogata; hacer que algo arda y dé luz.', 'En el Nuevo Testamento este verbo aparece exclusivamente con el sentido de encender o prender: lámparas en tres pasajes lucanos y fuego en otros dos. Jesús enseña que nadie enciende una lámpara para esconderla (Lc 8:16; 11:33), y la mujer que busca su moneda perdida enciende una lámpara para encontrarla (Lc 15:8). También describe cómo se encendió una fogata en el patio durante el juicio de Jesús (Lc 22:55) y cómo los isleños prendieron fuego para los náufragos de Pablo (Hch 28:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0683', 'spa', 'Empujar, rechazar o repudiar; usado metafóricamente para el rechazo de la palabra de Dios, del pacto o del pueblo de Dios.', 'ἀπωθέω combina ''lejos'' con ''empujar'', produciendo una imagen vívida de rechazo enérgico. En el NT aparece casi exclusivamente en sentido metafórico: no un empujón físico, sino el repudio deliberado de la verdad o la autoridad divina. Esteban relata cómo los antepasados de Israel rechazaron a Moisés (Hechos 7:27, 39); Pablo y Bernabé declaran que su audiencia ''desechó'' la palabra de Dios (Hechos 13:46); Pablo insiste en que Dios no ha ''rechazado'' a su pueblo (Romanos 11:1-2); y el naufragio en la fe de Himeneo y Alejandro se describe como haber ''rechazado'' la buena conciencia (1 Timoteo 1:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0684', 'spa', 'Destrucción, perdición, ruina total; también desperdicio o pérdida de algo valioso.', 'Destrucción, perdición, ruina total; también desperdicio o pérdida de algo valioso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0686', 'spa', 'Entonces, pues, por tanto — partícula ilativa que extrae conclusiones; raramente marcador interrogativo de incertidumbre', 'Una pequeña pero poderosa bisagra lógica en la argumentación griega: ἄρα señala que lo que sigue es consecuencia de lo anterior. Jesús la emplea para cerrar argumentos: «por sus frutos los conoceréis» (Mt 7:20), «si yo por el Espíritu de Dios echo fuera los demonios, entonces (ἄρα) el reino de Dios ha llegado a vosotros» (Mt 12:28). Pablo la utiliza incansablemente en Romanos para encadenar razonamientos teológicos. En un caso especial (Hch 8:30), acentuada con circunflejo, se convierte en partícula interrogativa: la delicada pregunta de Felipe al etíope: «¿Acaso entiendes lo que lees?».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0687', 'spa', 'partícula interrogativa que expresa indagación ansiosa o tentativa: ''¿acaso?'', ''¿quizás?'', ''¿será que...?''', 'La partícula ἆρα (con circunflejo, distinta de la inferencial ἄρα) introduce preguntas teñidas de incertidumbre, ansiedad o genuina indagación sobre un resultado. En el griego clásico podía esperar respuesta tanto afirmativa como negativa según el contexto, y esta flexibilidad se mantiene en sus cuatro apariciones neotestamentarias. En Marcos 11:13, Jesús se acerca a la higuera preguntándose «si acaso» hallará fruto; en Lucas 18:8, el Hijo del Hombre se pregunta si hallará fe en la tierra; en Hechos 8:22, Pedro insta a Simón a arrepentirse «si quizás» Dios le perdone; y en Hechos 17:27, Pablo dice que Dios dispuso la historia para que los hombres «quizás» buscasen a Dios y lo hallaran.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0688', 'spa', 'Arabia, la península o región arábiga', 'Nombre propio geográfico que se refiere a la península arábiga o al territorio árabe más amplio. Pablo menciona ir a Arabia en Gálatas 1:17 después de su conversión y antes de regresar a Damasco. En Gálatas 4:25, hace una conexión tipológica entre Agar, el monte Sinaí y Arabia. Los escritores griegos clásicos usaban el término para las tierras árabes, a menudo asociadas con rutas comerciales y regiones desérticas. La Septuaginta estableció la conexión entre Arabia y la ubicación del Sinaí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0689', 'spa', 'Aram -- nombre propio en la genealogía de Jesús, correspondiente al hebreo Ram (hijo de Hezrón)', 'Aram es la forma griega indeclinable del nombre hebreo Ram (ram, ''exaltado''), que aparece en las genealogías de Jesús en Mateo y Lucas. En Matt 1:3-4 se le nombra como hijo de Hezrón y padre de Aminadab, situándolo en la línea directa de la tribu de Judá desde Fares hasta David (cf. Ruth 4:19; 1 Chr 2:9-10). Lucas 3:33 presenta variantes textuales: algunos manuscritos leen Arní o Admín junto a Aram, lo cual refleja las conocidas complejidades de la tradición genealógica lucana. El nombre se conserva de manera uniforme en las distintas lenguas, confirmando su condición de simple nombre propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0692', 'spa', 'Ocioso, perezoso, sin trabajo; por extension: descuidado, inutil, que no produce buen resultado.', 'Adjetivo formado con alfa privativa + ἔργον (obra), literalmente ''sin obra.'' Se aplica primero a personas que estan sin hacer nada: jornaleros en la plaza esperando ser contratados (Mt 20:3, 6) o viudas jovenes que andan de casa en casa en inquietud improductiva (1 Ti 5:13). Un matiz metaforico mas agudo aparece cuando se aplica a palabras y a la fe: toda palabra ''ociosa'' enfrentara juicio (Mt 12:36), y la fe sin obras es ''inutil'' (Stg 2:20). El proverbio cretense citado en Tito 1:12 vincula la pereza con el fracaso moral. El castellano capta bien la distincion entre persona y cosa: ''ociosos'' para trabajadores inactivos, ''ociosa/inutil'' para la fe vacia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0693', 'spa', 'De plata, hecho de plata; objetos argénteos', 'Este adjetivo describe objetos fabricados de plata o el metal mismo. Demetrio, el platero, fabricaba templos «de plata» de Artemisa en Éfeso (Hch 19:24). Pablo menciona una casa grande que contiene utensilios de oro y «de plata» (2 Ti 2:20). Apocalipsis enumera ídolos de oro, «de plata» y otros materiales que la gente se negó a abandonar (9:20). En cada caso, la plata representa riqueza material, artesanía, o bien, en el contexto de la idolatría, una adoración mal dirigida. El valor del metal lo hacía significativo tanto para el comercio como para los objetos de culto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0694', 'spa', 'Plata como metal o moneda; dinero en general, ya sean monedas literales o riqueza figurada.', 'Plata como metal o moneda; dinero en general, ya sean monedas literales o riqueza figurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0696', 'spa', 'Plata, como metal precioso o material; usada para monedas, ídolos y materiales de construcción en el NT.', 'Este sustantivo designa la plata como sustancia física, a diferencia del término para moneda acuñada (ἀργύριον). Jesús instruye a los discípulos a no llevar oro, plata ni cobre en sus cinturones (Mt 10:9), donde la plata forma parte de una tríada de metales monetarios. Pablo argumenta que la naturaleza divina no se asemeja al oro, la plata ni la piedra labrados por el arte humano (Hch 17:29). En 1 Co 3:12 la plata aparece entre los materiales de construcción probados por el fuego. Santiago advierte a los ricos que su plata se ha corroído (Stg 5:3), y Apocalipsis la incluye entre las mercancías lujosas de Babilonia (Ap 18:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0697', 'spa', 'Areios Pagos -- el Areópago; la colina de Marte en Atenas, el antiguo tribunal y su cumbre rocosa', 'Ἄρειος Πάγος (''Colina de Ares'' o ''Colina de Marte'') designa tanto la prominencia rocosa al noroeste de la Acrópolis de Atenas como el venerable consejo que allí se reunía. El término combina Ἄρειος (''de Ares/Marte'', el dios de la guerra) con πάγος (''roca, colina''). En Acts 17:19-22, donde se concentran las cuatro apariciones neotestamentarias, Pablo es llevado al Areópago para exponer su enseñanza sobre Jesús y la resurrección. Si se refiere a la colina física o a una sesión formal del tribunal es materia de debate, pero el texto griego emplea tanto el sentido locativo (''en el Areópago'', v. 22) como el direccional (''al Areópago'', v. 19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0700', 'spa', 'Agradar o ser agradable a alguien; actuar de modo que se gane el favor o se satisfagan las expectativas de otro.', 'Agradar o ser agradable a alguien; actuar de modo que se gane el favor o se satisfagan las expectativas de otro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0701', 'spa', 'ἀρεστός -- agradable, aceptable; aquello que satisface o halla favor ante alguien', 'El adjetivo ἀρεστός (''agradable, aceptable'') describe acciones o personas que reciben aprobación o producen satisfacción. En el griego clásico abarcaba desde ''suficiente'' (de una cantidad de vino) hasta ''aceptable'' (de una persona a juicio de otra). Sus cuatro usos neotestamentarios abarcan contextos teológicos y políticos: Jesús declara que siempre hace lo ''agradable'' al Padre (John 8:29); los apóstoles juzgan que ''no es conveniente'' descuidar la palabra de Dios (Acts 6:2); Herodes vio que perseguir a los cristianos era ''agradable'' a los judíos (Acts 12:3); y los creyentes deben hacer lo ''agradable'' ante Dios (1 John 3:22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0703', 'spa', 'Virtud, excelencia moral o cualidad digna de elogio; también las proezas o atributos gloriosos de Dios.', 'En el griego clásico, esta palabra abarcaba toda forma de excelencia: destreza física, brillantez intelectual y carácter moral. El Nuevo Testamento la emplea en dos direcciones relacionadas pero distintas. Pablo la incluye en su célebre catálogo de cualidades dignas de elogio: «todo lo que es verdadero, noble, justo… si hay alguna virtud (ἀρετή)» (Fil 4:8). Pedro la aplica tanto a las «proezas» o «excelencias» de Dios que los creyentes están llamados a proclamar (1 Pe 2:9) como a la virtud moral que deben cultivar junto con la fe (2 Pe 1:3, 5). Este doble énfasis —las obras gloriosas de Dios y el esfuerzo ético humano— le confiere al término una rica textura teológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0705', 'spa', 'Contar, enumerar; determinar el número total de algo', 'Este verbo significa contar o numerar algo. Jesús asegura a sus discípulos que hasta los cabellos de sus cabezas están todos «contados» por Dios (Mt 10:30; Lc 12:7): el conocimiento divino se extiende hasta el detalle más mínimo. Apocalipsis 7:9 describe una gran multitud que nadie podía «contar», resaltando su inmensidad más allá de todo cálculo humano. La palabra enfatiza tanto el acto de enumerar como el resultado: un total determinado. El conocimiento exhaustivo de Dios contrasta con la incapacidad humana de contar vastas asambleas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0706', 'spa', 'Número — una cuenta, total o cantidad numérica de personas o cosas.', 'Número — una cuenta, total o cantidad numérica de personas o cosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0707', 'spa', 'Arimathaia -- Arimatea; una ciudad de Judea, hogar de José quien sepultó a Jesús', 'Ἁριμαθαία es la forma griega de un topónimo judío, tradicionalmente identificado con Ramataim-sofim (1 Sam 1:1), lugar de nacimiento del profeta Samuel. En el Nuevo Testamento aparece exactamente una vez en cada Evangelio (Matt 27:57; Mark 15:43; Luke 23:51; John 19:38), siempre como la ciudad de origen de José, el acaudalado y justo miembro del consejo que pidió a Pilato el cuerpo de Jesús y lo depositó en su propio sepulcro nuevo. Solo Lucas añade que José ''esperaba el reino de Dios'', mientras que Mateo especifica que era discípulo. El nombre pasa a todas las lenguas con mínima adaptación, testimoniando el papel universalmente reconocido de esta ciudad en el relato de la sepultura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0708', 'spa', 'Aristarco: cristiano macedonio de Tesalónica, compañero y compañero de prisión de Pablo.', 'Aristarco (cuyo nombre significa «el mejor gobernante») fue un creyente tesalonicense de Macedonia que acompañó a Pablo en varios viajes y compartió sus encarcelamientos. Aparece por primera vez cuando la turba lo arrastra durante el motín de Éfeso (Hch 19:29), y luego figura entre los compañeros de viaje de Pablo por Macedonia (Hch 20:4) y en la travesía a Roma (Hch 27:2). Pablo lo llama «compañero de prisión» en Col 4:10 y «colaborador» en Flm 1:24, lo cual indica una profunda lealtad personal en medio de circunstancias peligrosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0709', 'spa', 'Almorzar, comer, tomar una comida (desayuno o almuerzo)', 'Este verbo se refiere a comer una comida, en especial el desayuno o el almuerzo. Jesús acepta la invitación de un fariseo a «comer» con él (Lc 11:37). Tras la resurrección, Jesús invita a los discípulos a «desayunar» junto al mar de Tiberíades y luego pregunta tres veces a Pedro sobre su amor (Jn 21:12, 15). Originalmente el término designaba la comida matutina (ἄριστον), pero más tarde pasó a significar el almuerzo. En los contextos del Nuevo Testamento, marca momentos de comunión y conversación significativa, sobre todo en los encuentros posteriores a la resurrección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0710', 'spa', 'ἀριστερός -- izquierdo, del lado izquierdo; la mano izquierda en contraposición a la derecha', 'El adjetivo ἀριστερός (''izquierdo, del lado izquierdo'') designa la orientación espacial opuesta a la derecha (δεξιός). En el griego clásico llevaba connotaciones negativas: los augurios del lado izquierdo eran desfavorables, y ''hacia la izquierda'' significaba metafóricamente errar o lo siniestro. Las cuatro apariciones neotestamentarias conservan el sentido espacial sin los matices ominosos: Jesús instruye que la mano izquierda no debe saber lo que hace la derecha al dar limosna (Matt 6:3); Santiago y Juan solicitan sentarse a su izquierda y derecha en la gloria (Mark 10:37); los dos criminales penden a su izquierda y derecha en el Gólgota (Luke 23:33); y Pablo se recomienda mediante armas de justicia a diestra y siniestra (2 Cor 6:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0712', 'spa', 'Comida, banquete, festín; una ocasión formal de comer, especialmente en contextos de hospitalidad y celebración', 'Este sustantivo designa una comida o banquete, particularmente un evento formal. En la parábola de las bodas, el rey anuncia que «mi banquete está preparado» para los invitados que pusieron excusas (Mt 22:4). Un fariseo se sorprende cuando Jesús se sienta a comer sin lavarse ceremonialmente antes (Lc 11:38). Jesús aconseja que al dar un banquete se invite a los pobres y discapacitados en lugar de a amigos y parientes (Lc 14:12). El término aparece frecuentemente en contextos de hospitalidad, obligación social y enseñanza del reino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0713', 'spa', 'Suficiente, bastante, adecuado para lo que se necesita', 'Este adjetivo significa suficiente o bastante para un propósito determinado. Jesús enseña que a cada día le basta su propio mal, sin necesidad de añadir la ansiedad del mañana (Mt 6:34). Les dice a sus discípulos que le basta al discípulo llegar a ser como su maestro (Mt 10:25). Pedro escribe que el tiempo pasado fue suficiente para hacer lo que deseaban los gentiles, y ahora corresponde vivir de otra manera (1 Pe 4:3). La palabra enfatiza lo adecuado sin exceso, el contentamiento con lo que cubre la necesidad y la completitud de una medida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0714', 'spa', 'Ser suficiente o bastar; en voz media, estar contento o satisfecho con lo que se tiene.', 'Verbo que en voz activa significa ''ser suficiente'' y en voz media/pasiva pasa a significar ''estar contento, estar satisfecho.'' Cuando Felipe dice que doscientos denarios de pan no ''bastarian'' (Jn 6:7), y cuando Jesus le dice a Felipe que ver al Padre le ''bastaria'' (Jn 14:8), el enfoque recae en la suficiencia objetiva. Pero cuando Juan el Bautista dice a los soldados que se ''contenten'' con su paga (Lc 3:14), y cuando el autor de Hebreos exhorta a contentarse con lo que se tiene (He 13:5), el enfoque se desplaza hacia una disposicion interior del corazon. El encuentro de Pablo con la gracia divina une ambos sentidos: ''Te basta mi gracia'' (2 Co 12:9), objetivamente suficiente y a la vez llamado a descansar satisfecho en ella.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0716', 'spa', 'ἅρμα -- carro, carroza; vehículo con ruedas tirado por caballos, usado para viajes o guerra', 'El sustantivo neutro ἅρμα (''carro'') designa un vehículo con ruedas tirado por caballos, abarcando desde carros de guerra hasta carruajes de viaje. En el griego clásico también podía referirse metonímicamente al tiro de caballos. Las cuatro apariciones en el Nuevo Testamento se reparten entre dos escenas vívidas: en Hechos 8:28-38, el eunuco etíope lee a Isaías mientras viaja en su carro por el camino de Gaza, y Felipe corre a su lado, sube y lo bautiza — aquí ἅρμα es un carruaje de viaje. En Apocalipsis 9:9, el estruendo de las alas de las langostas demoníacas se compara con el sonido de carros que se lanzan a la batalla, evocando la tradición del carro de guerra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0720', 'spa', 'El verbo griego ἀρνέομαι es la palabra del Nuevo Testamento para el acto devastador de la negación — la más memorable, la triple negación de Pedro: ''N', 'El verbo griego ἀρνέομαι es la palabra del Nuevo Testamento para el acto devastador de la negación — la más memorable, la triple negación de Pedro: ''No conozco al hombre'' (Mateo 26:70-74). Con 33 apariciones, abarca desde la negación personal hasta la renuncia teológica y el rechazo tajante. Su sentido más frecuente es la negación de asociación con una persona o la repudiación de una verdad: negar a Cristo (Mateo 10:33), negar la fe (1 Timoteo 5:8; Apocalipsis 2:13). Pero también sirve para la abnegación — ''niéguese a sí mismo y tome su cruz'' (Lucas 9:23) — y para el llamado de Tito 2:12 a renunciar a la impiedad. En español, negar y renunciar captan el núcleo de la desautorización, mientras que el sentido de rechazo en Hebreos 11:24 (Moisés ''rehusó'' ser llamado hijo de la hija de Faraón) apunta hacia rehusar y un registro volitivo distinto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0721', 'spa', 'Diminutivo que significa ''corderito'', esta palabra aparece treinta veces en el Nuevo Testamento, veintinueve de ellas en Apocalipsis como título crist', 'Diminutivo que significa ''corderito'', esta palabra aparece treinta veces en el Nuevo Testamento, veintinueve de ellas en Apocalipsis como título cristológico definitorio del Cristo resucitado. El Cordero se presenta ''como inmolado'' y sin embargo ejerce autoridad soberana — abriendo sellos, recibiendo adoración y venciendo toda oposición (Apocalipsis 5:6-13; 17:14). La única aparición fuera de Apocalipsis es el tierno encargo de Jesús a Pedro: ''Apacienta mis corderitos'' (Juan 21:15), donde el diminutivo transmite la vulnerabilidad de los creyentes jóvenes. En español, Cordero se escribe con mayúscula cuando se usa como título, reflejando su elevada fuerza cristológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0722', 'spa', 'Arar, labrar la tierra; trabajar el suelo para la siembra', 'Este verbo significa arar o labrar la tierra con fines agrícolas. Jesús pregunta retóricamente si un siervo que está arando regresa del campo esperando agradecimiento inmediato (Lc 17:7). Pablo cita el principio de que quien ara debe arar con esperanza de participar de la cosecha (1 Co 9:10, dos veces). La imagen agrícola ilustra principios espirituales sobre el servicio, el trabajo y la justa expectativa de sustento. Arar representa la ardua labor preparatoria que anticipa la recompensa futura, fundamento del argumento paulino sobre el sostenimiento de los obreros del evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0724', 'spa', 'Codicia, rapiña, despojo; acción de apoderarse de lo ajeno por avaricia o violencia', 'Este sustantivo denota robo, rapiña o la codicia que impulsa tal apropiación. Jesús condena a los escribas y fariseos por limpiar el exterior de la copa mientras por dentro está llena de «rapiña y desenfreno» (Mt 23:25; Lc 11:39). Hebreos 10:34 elogia a los creyentes por aceptar con gozo «el despojo» de sus bienes, sabiendo que poseían algo mejor y perdurable. La palabra abarca tanto el acto de arrebatar como la disposición codiciosa que lo motiva. El sentido clásico de incautación violenta se mantiene en el uso neotestamentario de apropiación rapaz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0726', 'spa', 'Arrebatar o apoderarse por la fuerza; ser arrebatado en transporte divino; saquear o llevarse bienes.', 'Arrebatar o apoderarse por la fuerza; ser arrebatado en transporte divino; saquear o llevarse bienes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0727', 'spa', 'Rapaz, codicioso, depredador; como sustantivo, ladrón, estafador o extorsionador.', 'Este adjetivo convertido en sustantivo describe a alguien que toma por la fuerza lo que pertenece a otros: una persona depredadora y codiciosa. Jesús lo usa de manera memorable al hablar de lobos con piel de oveja que son «rapaces» (Mt 7:15), y el fariseo en el templo da gracias a Dios por no ser como los «ladrones» (Lc 18:11). Pablo incluye al ἅρπαξ junto con los avaros, idólatras y borrachos en sus listas de quienes quedan excluidos del reino de Dios (1 Co 5:10-11; 6:10). El verbo subyacente ἁρπάζω («arrebatar») revela la fuerza etimológica del término: se trata de personas que se apoderan de lo ajeno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0728', 'spa', 'Arras, anticipo, garantía; primera entrega que asegura el pago completo venidero', 'Este sustantivo designa un depósito o arras que garantizan el pago futuro completo. Pablo lo emplea exclusivamente en sentido espiritual: Dios ha dado a los creyentes el Espíritu como «arras» que garantizan nuestra herencia (Ef 1:14), como «anticipo» de lo que ha de venir (2 Co 1:22; 5:5). Este término comercial, proveniente de la práctica mercantil semítica, se convierte en una poderosa metáfora teológica. La presencia del Espíritu en el creyente es tanto prueba de pertenencia como primer pago de la gloria futura de la resurrección. Lo que experimentamos ahora es el adelanto de la redención plena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0730', 'spa', 'Varón; persona de sexo masculino, distinguido de la mujer, usado en contextos de creación, moral y ley mosaica.', 'Ἄρσην es el adjetivo griego estándar sustantivado para designar al ''varón'', formando el contrapunto natural de θῆλυς (''hembra''). Su uso más fundamental en el NT aparece en la apelación de Jesús a la creación: ''varón y hembra los hizo'' (Mt 19:4; Mr 10:6), citando Génesis 1:27 para fundamentar la teología del matrimonio. Lucas 2:23 cita la ley mosaica que establece que todo primogénito varón será consagrado al Señor. Pablo lo emplea en Romanos 1:27 para describir las relaciones entre personas del mismo sexo como un alejamiento del orden creado, y Gálatas 3:28 declara que en Cristo no hay varón ni mujer. Apocalipsis 12:5 lo aplica al hijo varón destinado a gobernar las naciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0732', 'spa', 'Enfermo, doliente; físicamente débil o achacoso; se usa para quienes necesitan sanidad corporal.', 'Describe a una persona físicamente enferma o debilitada por una dolencia. En los Evangelios aparece en contextos del ministerio sanador de Jesús: las multitudes le traen a los enfermos (Mt 14:14) y los discípulos ungen con aceite a los dolientes (Mr 6:13). Pablo también lo emplea en 1 Co 11:30 para describir la debilidad entre la asamblea corintia. El término se refiere de manera consistente a padecimientos corporales concretos, distinguiéndolo de la mera debilidad espiritual o moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0733', 'spa', 'varones que practican actos homosexuales', 'Sustantivo compuesto que literalmente significa ''acostadores de varones'', refiriéndose a hombres que tienen relaciones sexuales con varones. Pablo incluye este término en dos listas de vicios (1 Corintios 6:9; 1 Timoteo 1:10) entre prácticas incompatibles con el reino de Dios o la sana doctrina. El término aparece raramente en la literatura griega, siempre con connotación negativa. El uso clásico se refería a pederastia o prostitución masculina, aunque el alcance preciso sigue siendo debatido entre eruditos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0735', 'spa', 'Artemisa; la diosa griega adorada en Éfeso, cuyo templo era una de las Siete Maravillas del mundo antiguo.', 'Nombre propio de la diosa Artemisa, deidad patrona de Éfeso cuyo magnífico templo atraía peregrinos y sostenía un próspero comercio de plateros. Las cinco apariciones en el NT se concentran en Hechos 19, donde la predicación de Pablo provoca un motín entre los artesanos que fabrican santuarios de plata de Artemisa. El grito de la multitud «¡Grande es Artemisa de los efesios!» (Hch 19:28, 34) refleja el fervor cívico-religioso en torno a su culto. El genitivo Ἀρτέμιδος en el texto griego indica posesión referida a su templo y adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0737', 'spa', 'Adverbio que ancla la acción en el presente inmediato, a menudo con matiz de ''ahora mismo'' o ''en este preciso momento''. En el Nuevo Testamento aparece', 'Adverbio que ancla la acción en el presente inmediato, a menudo con matiz de ''ahora mismo'' o ''en este preciso momento''. En el Nuevo Testamento aparece en declaraciones de urgencia temporal y contraste — Jesús dice a Juan el Bautista ''permítelo por ahora'' (Mateo 3:15), y a sus discípulos ''no me veréis desde ahora en adelante'' (Mateo 23:39). La palabra puede deslizarse hacia el pasado reciente (''hace un momento'', como cuando el gobernante dice que su hija ''acaba de morir'', Mateo 9:18) o enfatizar el presente en contraste con lo venidero. Las traducciones convergen uniformemente en un marcador de tiempo presente: español ''ahora'', francés ''maintenant'', alemán ''jetzt''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0740', 'spa', 'Pan, hogaza — alimento de grano cocido como sustento diario; figuradamente, el pan de vida, el pan de la Presencia y el pan eucarístico', 'Ἄρτος es la palabra griega común para pan u hogaza, con 97 apariciones en el Nuevo Testamento. Como alimento básico del Mediterráneo antiguo, el pan figura en los relatos de milagros — la multiplicación de los cinco mil (Mt 14:17-19) y de los cuatro mil (Mt 15:34-36) — y en la petición «el pan nuestro de cada día, dánoslo hoy» (Mt 6:11). Jesús lo transforma en símbolo cristológico: «Yo soy el pan de vida» (Jn 6:35), y en la Última Cena el pan se convierte en signo de su cuerpo entregado por muchos (Mt 26:26; 1 Co 11:23-24). El trasfondo veterotestamentario del pan de la Presencia (Mt 12:4) y el maná en el desierto confiere a la palabra capas de memoria aliancística que cada ocurrencia en los Evangelios activa implícitamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0741', 'spa', 'Sazonar, dar sabor; agregar sabor o preservar mediante condimentado', 'Este verbo significa sazonar los alimentos, dándoles sabor o conservándolos. Jesús lo emplea metafóricamente: si la sal pierde su sabor, ¿cómo podrá ser sazonada de nuevo? Se vuelve inútil (Marcos 9:50; Lucas 14:34). Pablo instruye que nuestra conversación debe ser siempre con gracia, «sazonada con sal», para saber responder a cada persona (Colosenses 4:6). La imagen culinaria se transforma en metáfora de preservar la eficacia y añadir gracia. Así como la sal sazona y conserva los alimentos, las palabras del creyente deben estar marcadas por una gracia que las haga agradables y conservadoras de la verdad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0743', 'spa', 'arcángel, un ángel jefe o gobernante', 'Término que significa ángel jefe o arcángel, denotando un ser angelical de alto rango. Pablo menciona la voz del arcángel anunciando el regreso de Cristo (1 Tesalonicenses 4:16). Judas se refiere a ''Miguel el arcángel'' disputando con el diablo sobre el cuerpo de Moisés (Judas 1:9). El compuesto combina ''gobernante/jefe'' con ''ángel'', indicando estructura jerárquica en el reino angelical. La literatura apocalíptica judía desarrolló elaboradas angelologías presentando arcángeles como líderes de huestes celestiales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0744', 'spa', 'Antiguo, viejo, desde el principio — relativo a lo que existió hace mucho tiempo o a personas y cosas de épocas anteriores. El adjetivo ἀρχαῖος (archa', 'Antiguo, viejo, desde el principio — relativo a lo que existió hace mucho tiempo o a personas y cosas de épocas anteriores. El adjetivo ἀρχαῖος (archaios) describe lo que es antiguo, original o perteneciente a tiempos anteriores. Jesús lo emplea en el Sermón del Monte cuando dice: ''Oísteis que fue dicho a los antiguos'' (Mt 5:21, 33), estableciendo su autoridad para cumplir y superar la enseñanza antigua de la Torá. Las multitudes especulan que ''uno de los antiguos profetas'' ha resucitado (Lc 9:8, 19). En Hechos, Pedro apela a lo que Dios decidió ''en los primeros días'' (Hch 15:7), y Jacobo señala que Moisés ha sido proclamado ''desde generaciones antiguas'' (Hch 15:21). Apocalipsis llama a Satanás ''la serpiente antigua'' (Ap 12:9; 20:2), vinculándolo con el relato de Génesis.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0746', 'spa', 'Principio, origen; gobernante o principado cósmico; dominio o cargo de autoridad; esquina o extremo', 'Uno de los sustantivos de mayor carga teológica del Nuevo Testamento. Juan abre su Evangelio con ἐν ἀρχῇ — «en el principio» — en eco deliberado de Génesis 1:1, anclando a Cristo en el orden precreacional. Pablo emplea la misma palabra para los «principados» (ἀρχαί) invisibles del ámbito espiritual (Ro 8:38; Col 1:16), un desplazamiento del tiempo a la jerarquía que el español capta alternando entre «principio» y «principados». Un tercer uso abstrae aún más hacia el «dominio» o la esfera de la autoridad misma (1 Co 15:24). Finalmente, Hechos 10:11 reutiliza la palabra concretamente para las «puntas» del lienzo de la visión de Pedro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0747', 'spa', 'ἀρχηγός -- autor, fundador, pionero; quien abre camino y establece algo nuevo', 'El sustantivo ἀρχηγός combina ἀρχή (''principio, gobierno'') con ἄγω (''conducir''), produciendo un término rico que abarca ''fundador'', ''autor'', ''pionero'' y ''príncipe''. El griego clásico lo usaba para fundadores de ciudades, héroes tutelares y jefes gobernantes. En las cuatro apariciones neotestamentarias — todas en Hechos y Hebreos — se aplica exclusivamente a Cristo. Pedro llama a Jesús el ''Autor de la vida'' resucitado por Dios (Hechos 3:15) y el ''Príncipe y Salvador'' exaltado para conceder arrepentimiento y perdón (Hechos 5:31). Hebreos lo presenta como el ''pionero de la salvación'' perfeccionado mediante el sufrimiento (Hebreos 2:10) y el ''autor y consumador de la fe'' (Hebreos 12:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0749', 'spa', 'Sumo sacerdote, principal sacerdote — el oficial sacerdotal supremo del templo de Jerusalén, o colectivamente la cúpula sacerdotal', 'Ἀρχιερεύς combina ἀρχή (''principal, primero'') con ἱερεύς (''sacerdote'') para designar al sacerdote de más alto rango. En singular se refiere al sumo sacerdote que únicamente entraba en el Lugar Santísimo el Día de la Expiación — figuras como Caifás (Mt 26:57) y Anás (Jn 18:13). En plural, ''principales sacerdotes'' designa a la aristocracia sacerdotal que ejercía poder político en Jerusalén y aparece prominentemente en los relatos de la pasión como opositores de Jesús (Mt 21:23; 26:3). La carta a los Hebreos transforma el término teológicamente, declarando a Jesús sumo sacerdote eterno según el orden de Melquisedec (He 4:14–5:10). El español ''sumo sacerdote'', el francés ''grand prêtre'' y el alemán ''Hohepriester'' preservan la estructura compuesta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0751', 'spa', 'Arquipo, un colaborador cristiano de Pablo', 'Nombre propio que significa ''maestro de caballos'' o ''gobernante de caballos'', refiriéndose a un cristiano asociado con el círculo de Pablo. Pablo saluda a Arquipo en Colosenses 4:17, instándole a cumplir el ministerio que recibió en el Señor. En Filemón 1:2, Pablo lo llama ''nuestro compañero de milicia'', indicando estrecha asociación en la obra del evangelio. El lenguaje militar sugiere que Arquipo enfrentaba oposición o circunstancias ministeriales difíciles. Su papel exacto y ubicación permanecen inciertos, aunque la conexión con Colosas parece probable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0752', 'spa', 'Jefe de sinagoga; principal oficial laico que presidía el culto y la administración de la sinagoga judía.', 'El ἀρχισυνάγωγος era el líder laico encargado de organizar los servicios de culto en la sinagoga: seleccionaba a los lectores de las Escrituras, invitaba a los oradores y mantenía el orden. Este título aparece casi exclusivamente en los relatos sinópticos sobre Jairo, el padre desesperado cuya hija estaba muriendo (Mr 5:22-38; Lc 8:49; 13:14). Lucas 13:14 muestra al jefe de la sinagoga indignado porque Jesús sanó en sábado, revelando la tensión entre la autoridad institucional y el poder mesiánico. Hechos 13:15 y 18:8, 17 mencionan a jefes de sinagoga en el contexto de los viajes misioneros de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0755', 'spa', 'Maestresala, encargado del banquete; quien supervisa la organización y el servicio de un festín', 'Este sustantivo designa a la persona responsable de dirigir un banquete o festín, coordinando la comida y el servicio. En el relato de Juan sobre las bodas de Caná, los sirvientes llevan el agua convertida en vino al «maestresala», quien lo prueba sin conocer su origen y elogia al novio por haber reservado el mejor vino para el final (Juan 2:8-9). Este oficial era responsable de asegurar el éxito del banquete, probar los alimentos y el vino, y dirigir la celebración. Su asombro ante la calidad del vino resalta la naturaleza milagrosa de la primera señal de Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0756', 'spa', 'Comenzar, empezar — iniciar o dar comienzo a una acción, generalmente seguido de infinitivo', 'En el Nuevo Testamento, ἄρχομαι (la voz media de ἄρχω) funciona casi exclusivamente como auxiliar que significa «comenzar» o «empezar», rigiendo por lo general un infinitivo que especifica la acción que se inicia. Marca transiciones narrativas, señalando nuevas fases de actividad: Jesús «comenzó a predicar» (Mt 4:17), «comenzó a enseñar» (Mr 4:1), «comenzó a enviar» (Mr 6:7). Aunque el activo ἄρχω puede significar «gobernar» en griego clásico, el Nuevo Testamento emplea solo la voz media con fuerza incoativa. El español «comenzó», el francés commencer y el alemán anfangen confirman uniformemente este sentido único. La frecuencia del verbo (84 ocurrencias) refleja su importancia estructural en el estilo narrativo de los Evangelios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0757', 'spa', 'gobernar, ejercer autoridad, regir sobre otros', 'Un verbo que significa gobernar, dirigir o ejercer autoridad. Jesús señala que los gobernantes gentiles se enseñorean de sus súbditos (Marcos 10:42). Pablo cita la profecía de Isaías de que la raíz de Isaí se levantará ''para gobernar sobre los gentiles'' (Romanos 15:12). El uso clásico abarcaba comenzar/dirigir y gobernar/mandar, siendo primero en tiempo o primero en autoridad. Las ocurrencias del Nuevo Testamento se enfocan exclusivamente en el sentido de gobierno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0758', 'spa', 'Ἄρχων es el participio presente de ἄρχω (''gobernar'') usado como sustantivo, y designa a cualquier persona que ejerce autoridad de gobierno. En los Eva', 'Ἄρχων es el participio presente de ἄρχω (''gobernar'') usado como sustantivo, y designa a cualquier persona que ejerce autoridad de gobierno. En los Evangelios abarca desde el principal de la sinagoga que suplica a Jesús que resucite a su hija (Mateo 9:18, 23), hasta Nicodemo, ''un principal de los judíos'' (Juan 3:1), y el ominoso ''príncipe de los demonios'' aplicado a Beelzebú (Mateo 9:34; 12:24). Jesús mismo habla de ''el príncipe de este mundo'' siendo echado fuera (Juan 12:31; 14:30; 16:11), un uso que Pablo retoma con ''los gobernantes de este siglo que crucificaron al Señor de gloria'' (1 Corintios 2:6-8). Hechos lo aplica a miembros del Sanedrín (4:5, 8, 26) y a magistrados romanos (16:19). Las glosas multilingues convergen en autoridad: español ''gobernante/príncipe'', francés ''chef'', alemán ''Fuerst/Herrscher''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0759', 'spa', 'ἄρωμα -- especia, sustancia aromática; materiales fragantes usados en la preparación funeraria', 'El sustantivo neutro ἄρωμα (plural ἀρώματα) designa especias fragantes o sustancias aromáticas, particularmente las empleadas en las costumbres funerarias antiguas para ungir y preservar el cuerpo. Las cuatro apariciones neotestamentarias se agrupan en torno a la sepultura y resurrección de Jesús: las mujeres compran especias para ungir su cuerpo (Marcos 16:1), las preparan antes del reposo sabático (Lucas 23:56), las llevan a la tumba al amanecer del domingo (Lucas 24:1), y Nicodemo aporta una cantidad abundante de mirra y áloes para la envoltura inicial (Juan 19:40). La palabra pervive prácticamente sin cambios en numerosas lenguas europeas, testimonio de la perdurable memoria cultural de las prácticas aromáticas antiguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0760', 'spa', 'Asaf, nombre que aparece en la genealogía de Mateo', 'Un nombre hebreo (que significa ''recolector'' o ''recogedor'') que aparece en la genealogía de Jesús según Mateo. Las ediciones críticas modernas reconocen esto como probablemente una corrupción textual de ''Asa'', el rey de Judá (1 Reyes 15). La confusión pudo haber surgido porque Asaf era un famoso músico levita y salmista (Salmos 73-83), haciendo el nombre familiar a los escribas. La mayoría de las traducciones siguen los manuscritos que leen ''Asa'' en lugar de ''Asaf''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0761', 'spa', 'inconmovible, inamovible, firmemente fijo', 'Un adjetivo que significa incapaz de ser sacudido o movido. En Hechos 27:41, describe la proa del barco naufragado de Pablo quedando firmemente encallada en el fondo marino. En Hebreos 12:28, los creyentes reciben un reino inconmovible. El término combina el prefijo negativo con un verbo que significa ''sacudir'', produciendo el sentido de estabilidad ante fuerzas externas. El uso clásico lo aplicaba a Delos (míticamamente fijada por Zeus) y a la fe u ordenanzas inquebrantables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0762', 'spa', 'inextinguible, inagotable; fuego que no puede apagarse, especialmente el fuego del juicio divino', 'Formado a partir del alfa privativa y σβέννυμι (''apagar''), ἄσβεστος describe un fuego que desafía todo intento de ser extinguido. En los Evangelios Sinópticos, Juan el Bautista advierte que el que viene quemará la paja con ''fuego inextinguible'' (Mateo 3:12; Lucas 3:17), y el Jesús de Marcos invoca dos veces el ''fuego inextinguible'' de la Gehena (Marcos 9:43, 45). Aunque la palabra tenía fuerza práctica en el griego clásico — Homero la usaba para llamas que no se pueden sofocar —, en el NT pertenece enteramente al ámbito de la advertencia escatológica, subrayando la finalidad e inevitabilidad del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0763', 'spa', 'Impiedad, irreverencia; una disposición de falta de respeto hacia Dios y desprecio por las normas divinas.', 'ἀσέβεια designa la postura fundamental de irreverencia hacia Dios — no un acto malvado aislado, sino una disposición arraigada de impiedad. Pablo la introduce como blanco de la ira de Dios, revelada ''contra toda impiedad e injusticia'' (Romanos 1:18), emparejándola con ἀδικία (injusticia) tal como hacían los escritores griegos clásicos. Aparece en la promesa de que el Libertador ''apartará la impiedad de Jacob'' (Romanos 11:26), en advertencias sobre la propagación corrosiva de las palabras impías (2 Timoteo 2:16), en el llamado a renunciar a ''la impiedad y los deseos mundanos'' (Tito 2:12), y en la cita de Enoc que hace Judas contra los ''impíos'' (Judas 1:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0765', 'spa', 'Persona impía o irreverente, alguien que carece de reverencia hacia Dios y vive en desprecio de la ley divina. Adjetivo sustantivado que describe a un', 'Persona impía o irreverente, alguien que carece de reverencia hacia Dios y vive en desprecio de la ley divina. Adjetivo sustantivado que describe a una persona caracterizada por la irreverencia hacia Dios — no simplemente débil moralmente, sino activamente opuesta o indiferente al orden divino. Pablo lo aplica de manera programática en Romanos 4:5 y 5:6 para describir a las mismas personas por quienes Cristo murió para justificar, convirtiendo el término en algo central para la teología de la gracia. Judas 4, 15 y 2 Pedro 2:5 lo usan para caracterizar a quienes están bajo juicio escatológico. El español ''impío'', el hindi ''अभक्त'' (irreverente) y el árabe ''الفُجَّار'' (los malvados) transmiten impiedad activa más que mera ignorancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0766', 'spa', 'Lascivia, sensualidad, exceso moral desvergonzado y libertinaje sexual. Denota inmoralidad desenfrenada y desvergonzada — un desprecio descarado por l', 'Lascivia, sensualidad, exceso moral desvergonzado y libertinaje sexual. Denota inmoralidad desenfrenada y desvergonzada — un desprecio descarado por los límites morales que va más allá de la mera indulgencia hasta la escandalosa transgresión pública. Jesús la incluye entre los males que contaminan desde el interior (Mr 7:22), y Pablo la coloca en catálogos de vicios junto a la inmoralidad sexual y la impureza (Gá 5:19; 2 Co 12:21). Pedro advierte que los falsos maestros la explotan para atraer seguidores (2 P 2:2, 18). El rango semántico enfatiza el carácter flagrante y público del vicio: el árabe ''دَعارة'' (libertinaje), el español ''lascivia/libertinaje'' y el hindi ''लम्पटता'' (lujuria) subrayan el exceso desvergonzado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0768', 'spa', 'Aser, patriarca hebreo y ancestro tribal', 'Un nombre hebreo (que significa ''feliz'' o ''bendito'') que se refiere al octavo hijo de Jacob y la tribu descendiente de él. En Lucas 2:36, Ana la profetisa es identificada como de la tribu de Aser. En Apocalipsis 7:6, la tribu de Aser está listada entre los 144,000 sellados de las doce tribus. El territorio de Aser estaba en el norte de Israel a lo largo de la costa mediterránea. El nombre es indeclinable en griego, manteniendo su forma hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0769', 'spa', 'Debilidad o enfermedad; abarcando desde la fragilidad abstracta (física, moral, espiritual) hasta la dolencia corporal concreta', 'Debilidad o enfermedad; abarcando desde la fragilidad abstracta (física, moral, espiritual) hasta la dolencia corporal concreta');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0770', 'spa', 'Verbo que recorre todo el espectro de la fragilidad humana, desde la enfermedad física hasta la debilidad interior. En los Evangelios describe típicam', 'Verbo que recorre todo el espectro de la fragilidad humana, desde la enfermedad física hasta la debilidad interior. En los Evangelios describe típicamente a los enfermos que Jesús sana (Mateo 10:8; Juan 11:1-3), mientras que Pablo lo emplea para la vulnerabilidad espiritual y moral — haciéndose débil por causa de los débiles (1 Corintios 9:22), o reconociendo que la carne es débil aunque el espíritu esté dispuesto (Romanos 8:3). La distinción en español entre ''estar enfermo'' y ''ser débil'' refleja nítidamente los dos sentidos nucleares. El uso griego desde el siglo V a.C. ya abarcaba tanto la enfermedad corporal como la pobreza o la impotencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0772', 'spa', 'Débil, sin fuerza; carente de vigor en cuerpo, voluntad o posición social; específicamente enfermo o doliente en contextos de sanidad', 'Débil, sin fuerza; carente de vigor en cuerpo, voluntad o posición social; específicamente enfermo o doliente en contextos de sanidad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0773', 'spa', 'Asia — la provincia romana en el occidente de Asia Menor, con Éfeso como su capital.', 'Asia — la provincia romana en el occidente de Asia Menor, con Éfeso como su capital.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0779', 'spa', 'Odre: recipiente de cuero de animal para almacenar y transportar vino, central en la parabola de Jesus sobre el vino nuevo en odres viejos.', 'Odre: recipiente de cuero de animal para almacenar y transportar vino, central en la parabola de Jesus sobre el vino nuevo en odres viejos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0782', 'spa', 'Saludar o enviar saludos; dar la bienvenida o abrazar calurosamente; despedirse de alguien', 'Ἀσπάζομαι es uno de los verbos más arraigados en la vida social del Nuevo Testamento, con casi sesenta apariciones que recorren todo el arco del encuentro humano: desde el saludo inicial hasta el abrazo cordial y la despedida final. Las cartas de Pablo están saturadas de él: solo los capítulos finales de Romanos contienen más de veinte saludos a personas mencionadas por nombre, lo que convierte a ἀσπάζομαι en una ventana a las redes sociales de la iglesia primitiva. Su alcance se extiende más allá de las meras palabras al abrazo físico (Hch 21:7) e incluso al «saludo desde lejos» lleno de fe de Hebreos 11:13, donde los patriarcas acogieron las promesas de Dios sin haberlas aún recibido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0783', 'spa', 'Saludo o salutación, ya sea pronunciado en persona o escrito en una carta. Se refiere a una expresión hablada o escrita de bienvenida, respeto o bueno', 'Saludo o salutación, ya sea pronunciado en persona o escrito en una carta. Se refiere a una expresión hablada o escrita de bienvenida, respeto o buenos deseos. El término abarca una amplia variedad de contextos sociales: el saludo de María a Elisabet que hizo saltar al niño Juan en el vientre (Lc 1:29, 41, 44), los saludos en las plazas que los fariseos anhelaban (Mt 23:7; Mr 12:38; Lc 11:43; 20:46), y la práctica apostólica de cerrar cartas con un saludo personal de puño y letra (1 Co 16:21; Col 4:18; 2 Ts 3:17). El español ''saludo'', el hindi ''नमस्कार/अभिवादन'' y el árabe ''السَّلام/تَحِيَّة'' reflejan este concepto unificado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0784', 'spa', 'sin mancha, inmaculado; moral o ritualmente puro, libre de toda contaminación', 'Derivado del alfa privativa y σπίλος (''mancha''), ἄσπιλος describe aquello que está libre de toda mácula o impureza moral. El término opera tanto en el registro ético como en el cultual dentro del NT. Pedro lo aplica a Cristo como cordero ''sin mancha ni defecto'' (1 Pedro 1:19), evocando la imaginería sacrificial. Santiago define la ''religión pura'' como mantenerse ''sin mancha'' del mundo (Santiago 1:27). Pablo exhorta a Timoteo a guardar el mandamiento ''sin mácula'' hasta la manifestación de Cristo (1 Timoteo 6:14), y Pedro insta a los creyentes a ser hallados ''sin mancha'' en el retorno del Señor (2 Pedro 3:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0787', 'spa', 'asarion, pequeña moneda romana de cobre que vale aproximadamente 1/16 de denario', 'Un préstamo del latín que denota una pequeña moneda de cobre de valor mínimo. Jesús la usa en dichos sobre el cuidado de Dios por los gorriones: dos gorriones vendidos por un asarion (Mateo 10:29), cinco por dos asaria (Lucas 12:6). El punto es que incluso criaturas de valor económico insignificante son notadas por el Padre. El asarion equivalía aproximadamente a 1/16 de un denario (el salario de un día), haciéndola una moneda de muy poco poder adquisitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0789', 'spa', 'Asos, ciudad portuaria en la provincia romana de Asia', 'Ciudad griega en la costa noroeste de Asia Menor (actual Turquía), ubicada en la orilla sur del golfo de Adramitio. Hechos 20:13-14 describe el itinerario de viaje de Pablo: sus compañeros navegaron desde Troas hasta Asos mientras Pablo fue por tierra, reuniéndose con ellos allí antes de continuar hacia Mitilene. La ruta terrestre era unos 20 millas más corta que navegar alrededor del cabo Lecto. Asos era conocida por su empinada acrópolis y sarcófagos hechos de piedra local.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0791', 'spa', 'hermoso, bello, elegante, agradable a la vista', 'Adjetivo que significa hermoso, elegante o agradable en apariencia. Esteban es descrito como ''hermoso para Dios'' cuando era un bebé (Hechos 7:20). Los padres de Moisés vieron que era ''un niño hermoso'' y lo escondieron de Faraón (Hebreos 11:23). El uso clásico abarcaba desde ''refinado/urbano'' hasta ''ingenioso'' y elogio general de belleza. El Nuevo Testamento lo usa exclusivamente para atractivo físico, específicamente de infantes cuya apariencia motivó a sus padres a tomar acciones protectoras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0792', 'spa', 'Estrella: cuerpo celeste luminoso, usado literalmente para astros físicos y simbólicamente para ángeles o figuras exaltadas', 'Estrella: cuerpo celeste luminoso, usado literalmente para astros físicos y simbólicamente para ángeles o figuras exaltadas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0793', 'spa', 'inestable, inconstante, sin fundamento firme', 'Adjetivo que significa inestable o sin fundamento firme. Pedro advierte que las personas inestables distorsionan las Escrituras para su propia destrucción (2 Pedro 2:14; 3:16). El término combina un prefijo negativo con un verbo que significa ''fijar firmemente'' o ''apuntalar'', resultando en el sentido de carecer de fundamento firme. Puede describir inestabilidad física (sin apoyo) o inestabilidad moral/espiritual (sin arraigo). Pedro lo usa exclusivamente para inestabilidad espiritual: personas susceptibles a falsas enseñanzas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0794', 'spa', 'sin afecto natural, carente de amor familiar', 'Adjetivo que describe a personas desprovistas de afecto familiar natural. Pablo lo enumera entre los vicios que caracterizan la impiedad en los últimos días (Romanos 1:31; 2 Timoteo 3:3). El término niega ''storge'', la palabra griega para afecto familiar y amor paternal. Describe la escalofriante ausencia de vínculos instintivos que normalmente unen a las familias: padres que no aman a sus hijos, hijos que no cuidan a sus padres. El uso clásico lo aplicaba a comportamiento cruel o desalmado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0795', 'spa', 'Errar el blanco, desviarse, apartarse de la verdad', 'Este verbo significa errar el blanco o desviarse de un objetivo. Pablo lo usa en las Epístolas Pastorales para describir la desviación teológica. Algunos «erraron el blanco» respecto a ciertos asuntos y se volvieron a discusiones vacías (1 Timoteo 1:6). Otros se «desviaron» de la fe por amor al dinero (1 Timoteo 6:21). Dos hombres «erraron respecto a la verdad» al afirmar que la resurrección ya había ocurrido, trastornando la fe de algunos creyentes (2 Timoteo 2:18). La metáfora de fallar el tiro se aplica al extravío doctrinal y moral lejos de la verdad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0796', 'spa', 'Relámpago; por extensión, resplandor brillante o fulgor deslumbrante semejante a un destello de luz.', 'Designa principalmente el dramático destello del relámpago que rasga el cielo, un fenómeno natural cargado de significado teofánico en las Escrituras. Jesús compara su venida con un relámpago que resplandece de oriente a occidente (Mt 24:27), y las visiones de la sala del trono en Apocalipsis crepitan con relámpagos, estruendos y truenos (Ap 4:5; 8:5; 11:19; 16:18). El ángel junto al sepulcro vacío tiene una apariencia ''como un relámpago'' (Mt 28:3), tendiendo un puente entre lo literal y lo luminoso. En Lucas 11:36, la palabra describe no un relámpago atmosférico sino el resplandor brillante de una lámpara, una radiancia metafórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0797', 'spa', 'relampaguear, brillar intensamente como un rayo', 'Verbo que significa relampaguear o resplandecer como un rayo. Jesús describe su venida como el relámpago que destella de este a oeste (Lucas 17:24). En la resurrección, dos hombres con vestidura resplandeciente aparecen a las mujeres (Lucas 24:4). El uso clásico describía rayos de luz, armas o armaduras relucientes, y rostros brillantes. El Nuevo Testamento lo emplea para resplandor sobrenatural asociado con la presencia divina o eventos escatológicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0798', 'spa', 'estrella, cuerpo celeste; usado para estrellas literales y como figura de multitud innumerable', 'El griego ἄστρον designa una estrella o constelación, con un matiz más colectivo o poético que el más frecuente ἀστήρ. Lucas 21:25 sitúa señales en los astros entre los portentos cósmicos que precederán el regreso de Cristo. Hechos 7:43 cita Amós 5:26, refiriéndose a la «estrella de vuestro dios Refán», un ídolo astral. Hechos 27:20 relata cómo la nave de Pablo perdió de vista el sol y las estrellas durante una tempestad, dejando a los marineros sin referencia para navegar. Hebreos 11:12 invoca la promesa abrahámica, comparando la descendencia de Abraham con las estrellas en número.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0801', 'spa', 'Sin entendimiento; insensato, necio; que carece de capacidad o disposición para comprender la verdad espiritual o moral.', 'Designa a una persona que carece de discernimiento o se niega a ejercitar la comprensión. Jesús emplea este adjetivo para reprender a sus propios discípulos cuando no captan el sentido de una parábola (Mt 15:16; Mc 7:18), mientras que Pablo lo aplica tanto a los gentiles cuyo pensamiento se volvió vano (Ro 1:21, 31) como, citando Deuteronomio, a una ''nación insensata'' que provoca a Israel a celos (Ro 10:19). El término señala una deficiencia de percepción espiritual, no simplemente una falta de inteligencia natural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0803', 'spa', 'Certeza, seguridad, firmeza; garantía firme o protección contra el peligro', 'Este sustantivo denota seguridad, certeza o firmeza. Lucas escribe su Evangelio para que Teófilo conozca «la certeza» de las cosas que le fueron enseñadas (Lucas 1:4). La guardia del templo fue hallada en sus puestos «con toda seguridad», aunque los presos habían escapado (Hechos 5:23). Pablo advierte que cuando digan «paz y seguridad», vendrá sobre ellos destrucción repentina (1 Tesalonicenses 5:3). La palabra abarca tanto la certeza intelectual (conocimiento firme) como la seguridad física (protección contra el peligro), ambas insuficientes sin fundamento divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0804', 'spa', 'Seguro, firme, cierto; confiable y estable, que no puede fallar ni inducir a error; dicho de información fiable o esperanza inquebrantable.', 'Transmite la idea de firmeza, fiabilidad y seguridad, ya sea de hechos verificables o de una esperanza que no vacila. En Hechos, los funcionarios romanos buscan ''lo cierto'' (τὸ ἀσφαλές) sobre el caso de Pablo (Hch 21:34; 22:30; 25:26), queriendo información confiable en medio de la confusión. Pablo dice a los filipenses que repetir las mismas cosas es ''seguro'' para ellos (Fil 3:1), mientras que Hebreos 6:19 llama a la esperanza cristiana ancla del alma, ''segura y firme''. El núcleo semántico gira en torno a la seguridad y la confiabilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0805', 'spa', 'asegurar, sujetar firmemente, custodiar; fortificar un lugar o impedir la fuga de una persona', 'Derivado del adjetivo ἀσφαλής («firme, seguro»), este verbo significa hacer algo seguro o inamovible. Sus cuatro apariciones neotestamentarias se concentran en la narrativa de la pasión-resurrección y el encarcelamiento de Pablo. Los principales sacerdotes piden a Pilato que «asegure el sepulcro» (Mateo 27:64-65), y proceden a sellar la piedra y poner guardia (Mateo 27:66). En Hechos 16:24, el carcelero de Filipos «aseguró» los pies de Pablo y Silas en el cepo. El hilo semántico es constante: restricción física o fortificación para impedir la fuga o la manipulación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0806', 'spa', 'De forma segura, con certeza, firmemente; de manera firme y confiable', 'Este adverbio significa de forma segura, con certeza o firmemente. Judas buscó la oportunidad de entregar a Jesús «con seguridad», lejos de la multitud (Marcos 14:44). Pedro declara en Pentecostés que todo Israel sepa «con certeza» que Dios ha hecho a Jesús Señor y Cristo (Hechos 2:36). Al carcelero de Filipos se le ordena custodiar a Pablo y Silas «de forma segura» (Hechos 16:23). El adverbio enfatiza la firmeza, fiabilidad o seguridad con que se realiza algo, pudiendo denotar medidas de seguridad física o certeza epistemológica de conocimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0807', 'spa', 'comportarse de manera impropia o indecente', 'Un verbo que significa actuar de manera impropia o indecorosa. Pablo lo usa para referirse a un hombre que podría estar actuando inapropiadamente hacia su prometida (1 Corintios 7:36). También dice que el amor ''no se comporta indecentemente'' (1 Corintios 13:5). El término deriva de un prefijo negativo y ''schema'' (forma/apariencia), sugiriendo comportamiento que viola la forma o el decoro apropiado. El uso clásico incluía conducta vergonzosa o deshonrosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0808', 'spa', 'comportamiento vergonzoso, indecencia, partes privadas (eufemismo)', 'Un sustantivo que denota comportamiento vergonzoso o indecente, o que se refiere eufemísticamente a las partes privadas. Pablo describe los actos homosexuales como ''actos desvergonzados'' o ''indecencia'' (Romanos 1:27). Apocalipsis 16:15 advierte sobre andar desnudo y tener la vergüenza expuesta. El uso clásico abarcaba desde falta de gracia o torpeza hasta impropiedad moral y referencia eufemística a los genitales. La Septuaginta lo usaba para desnudez o exposición vergonzosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0810', 'spa', 'libertinaje, desenfreno, disipación; vida derrochadora y desenfrenada sin moderación moral', 'Este sustantivo designa una vida derrochadora y disoluta, marcada por el exceso y la falta de moderación moral. Pablo advierte a los creyentes que no se embriaguen con vino, lo cual conduce al «desenfreno», sino que se llenen del Espíritu (Ef 5:18). Tito debe designar ancianos cuyos hijos sean creyentes y no estén acusados de «vida disoluta» (Tit 1:6). Pedro describe cómo los gentiles se sorprenden cuando los creyentes ya no participan en «el mismo torrente de disipación» (1 P 4:4). El término combina el derroche material con la disolución moral, retratando una vida sin freno ni dirección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0814', 'spa', 'de manera desordenada, sin disciplina apropiada', 'Un adverbio que significa de manera desordenada, indisciplinada o irregular. Pablo advierte a los tesalonicenses que no se asocien con creyentes que andan desordenadamente (2 Tesalonicenses 3:6, 11). El contexto indica personas que no trabajan sino que se entrometen en asuntos ajenos. La palabra raíz describía soldados fuera de formación, ritmos irregulares en música o medicina, o comportamiento generalmente indisciplinado. El uso de Pablo se enfoca en cristianos que violan normas comunitarias respecto al trabajo y la responsabilidad mutua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0815', 'spa', 'sin hijos, sin descendencia; que carece de prole', 'Este adjetivo describe a una persona que no tiene hijos. Jesús lo emplea al responder la pregunta de los saduceos citando la ley de Moisés: si un hombre muere «sin hijos», su hermano debe casarse con la viuda para dar descendencia al difunto (Lc 20:28, 29, 30). El escenario plantea siete hermanos que se casan consecutivamente con la misma mujer, todos muriendo sin descendencia. El término resalta la ausencia de prole, lo cual en el contexto antiguo representaba la pérdida del legado familiar. La ley del levirato buscaba remediar esta crisis preservando la línea familiar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0816', 'spa', 'mirar fijamente, clavar la vista — fijar los ojos en alguien o algo con atención concentrada y sostenida', 'mirar fijamente, clavar la vista — fijar los ojos en alguien o algo con atención concentrada y sostenida');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0817', 'spa', 'sin, aparte de, en ausencia de', 'Una preposición que significa sin o aparte de, que toma el caso genitivo. Jesús pregunta a sus discípulos si recuerdan ser enviados ''sin bolsa'' (Lucas 22:35). Judas buscaba traicionar a Jesús ''sin multitud'' o ''lejos de la multitud'' (Lucas 22:6). La poesía épica y trágica usaba este término donde la prosa clásica prefería ''choris'' o ''aneu''. Enfatiza ausencia completa o separación de algo normalmente esperado o presente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0818', 'spa', 'Deshonrar, tratar con desprecio o vergüenza; insultar o degradar a alguien o algo.', 'Un verbo que significa deshonrar, tratar con vergüenza o menospreciar. Es la contraparte activa de ἄτιμος (sin honra) y aparece en contextos de degradación o insulto deliberado. En la parábola de los labradores malvados, los siervos enviados por el dueño de la viña son ''deshonrados'' — golpeados y despedidos con las manos vacías (Marcos 12:4; Lucas 20:11). Jesús declara que él no deshonra al Padre, volviendo la acusación contra sus adversarios (Juan 8:49). Los apóstoles se regocijan de haber sido tenidos por dignos de ''padecer afrenta'' por el Nombre (Hechos 5:41). En español, ''deshonrar'' y ''afrentar'' preservan fielmente la semántica del original griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0819', 'spa', 'Deshonra, desgracia o vergüenza; la condición de ser menospreciado o tratado con desprecio.', 'Designa el estado de carecer de honor, ya sea por degradación social, debilidad corporal o desgracia moral. Pablo lo emplea tanto para describir las pasiones vergonzosas a las que Dios entrega a las personas (Rom 1:26) como la condición humilde del cuerpo de resurrección sembrado en debilidad (1 Cor 15:43). La evidencia multilingüe converge de manera notable: español ''deshonra'', francés ''déshonneur'' y alemán ''Unehre'' reflejan la idea central de honor negado. En 2 Cor 6:8, Pablo lo empareja con ''honra'' para describir la experiencia apostólica paradójica de soportar la desgracia mientras se recibe honor de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0820', 'spa', 'sin honor, deshonrado, despreciado; tratado como carente de valor o dignidad', 'Formado a partir del alfa privativa y τιμή («honor, valor»), ἄτιμος describe a una persona o cosa privada de honor o considerada sin valor. Jesús cita el proverbio «no hay profeta sin honra sino en su propia tierra» (Mateo 13:57; Marcos 6:4), usando el adjetivo para nombrar la paradoja de que la familiaridad local engendra desprecio. Pablo adopta la palabra en su correspondencia corintia: llama a los apóstoles «despreciados» (1 Corintios 4:10) en su irónico catálogo de penalidades apostólicas, y en 1 Corintios 12:23 habla de los miembros «menos honorables» del cuerpo que reciben mayor honor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0821', 'spa', 'deshonrar, tratar con desprecio; privar de derechos civiles; castigar con pérdida de estatus', 'Verbo que describe acciones que disminuyen la honra o la posición de alguien. En voz activa significa deshonrar a una persona o tratarla con desprecio, despojándola del respeto o la dignidad que antes poseía. En voz pasiva indica sufrir deshonra o indignidad, experimentar degradación o falta de respeto. En contextos legales puede referirse a un castigo que implica la pérdida de derechos o privilegios cívicos (atimia), una privación formal del estatus de ciudadano. La palabra abarca tanto la deshonra social como la inhabilitación jurídica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0822', 'spa', 'vapor, neblina, exhalación, humo', 'Un sustantivo que denota vapor húmedo, humo o neblina que se eleva de líquido calentado. Pedro cita la profecía de Joel de ''sangre y fuego y vapor de humo'' que acompaña el día del Señor (Hechos 2:19). Santiago compara la vida humana con un vapor que aparece brevemente y luego se desvanece (Santiago 4:14). El uso clásico distinguía entre vapor húmedo (atmis) y humo seco (kapnos), aunque podían combinarse. El término enfatiza transitoriedad e insustancialidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0824', 'spa', 'fuera de lugar, impropio, malo; abarca desde lo meramente inusual hasta lo moralmente perverso', 'Literalmente «fuera de lugar» (del alfa privativa y τόπος, «lugar»), ἄτοπος cubre un amplio rango semántico que va desde lo extraño o inusual hasta lo moralmente reprobable. Lucas 23:41 tiene la mayor fuerza moral: el ladrón arrepentido declara que Jesús «nada malo ha hecho», en marcado contraste con los crímenes de ellos. Hechos 25:5 lo usa más suavemente: si hay «algo impropio» en Pablo, que lo acusen. Hechos 28:6 describe el daño físico esperado pero ausente tras una mordedura de serpiente: «nada extraño» le sucedió a Pablo. 2 Tesalonicenses 3:2 pide oración contra hombres «perversos y malos».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0829', 'spa', 'obstinado, arrogante, terco, complacido consigo mismo', 'Adjetivo que describe a alguien obstinado, arrogante o tercamente insistente en su propia voluntad. Pablo lo enumera entre las cualidades que un supervisor no debe tener (Tito 1:7). Pedro advierte sobre personas audaces y obstinadas que no temen blasfemar (2 Pedro 2:10). El término combina ''sí mismo'' y ''agradar'', sugiriendo alguien que solo se agrada a sí mismo sin consideración por los demás. El uso clásico incluía sentidos de terco, hosco o autocomplaciente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0830', 'spa', 'por propia voluntad, voluntario, elegido por uno mismo', 'Adjetivo que significa hecho por propia voluntad o iniciativa voluntaria. Pablo describe la generosidad de los macedonios como siendo de su propia voluntad (2 Corintios 8:3, 17). El término combina ''sí mismo'' y ''elegido'', enfatizando la acción voluntaria en lugar de la compulsión. El uso clásico lo aplicaba a magistrados autoelegidos, servicio voluntario o consecuencias autoinfligidas. Pablo lo usa positivamente para la generosidad libremente elegida que excede la presión externa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0832', 'spa', 'tocar la flauta, tañer; producir música con un instrumento de viento', 'Este verbo significa tocar la flauta o tañer un instrumento de viento. Jesús lo usa en su lamento sobre la respuesta de aquella generación tanto a Juan como a él mismo: «Os tocamos la flauta y no bailasteis» (Mt 11:17; Lc 7:32). Pablo pregunta retóricamente cómo pueden entenderse instrumentos inanimados como la flauta o el arpa si no producen notas diferenciadas (1 Co 14:7). En el primer caso, la flauta representa la música festiva; en el segundo, la necesidad de una comunicación clara. La metáfora musical ilumina la receptividad espiritual y la claridad del mensaje.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0833', 'spa', 'Patio o atrio de un edificio; redil o corral cerrado para ganado', 'Patio o atrio de un edificio; redil o corral cerrado para ganado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0834', 'spa', 'flautista, quien toca el aulos (instrumento de caña)', 'Sustantivo que denota a alguien que toca el aulos, un instrumento de viento de doble caña similar al oboe. Jesús encuentra flautistas en la casa de Jairo interpretando música de duelo acostumbrada (Mateo 9:23). El lamento de Apocalipsis sobre Babilonia incluye el silencio de los flautistas entre otros músicos (Apocalipsis 18:22). Los flautistas eran comunes en funerales y festivales en el mundo antiguo. El término griego también podía referirse a ciertas avispas o ingenieros sanitarios en textos especializados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0835', 'spa', 'pasar la noche, alojarse, acampar por la noche', 'Verbo que significa pasar la noche, alojarse o acampar. Jesús se alojó en Betania durante su última semana (Mateo 21:17). Lucas nota que Jesús pasaba las noches en el Monte de los Olivos mientras enseñaba en el templo de día (Lucas 21:37). El término originalmente se refería a quedarse en un patio (aule), luego se amplió a cualquier alojamiento nocturno o campamento militar. El uso clásico incluía ovejas acostándose en rediles, aves posándose o ejércitos acampando.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0837', 'spa', 'Crecer o aumentar; intransitivamente del crecimiento natural o espiritual, o causativamente cuando Dios concede el crecimiento', 'Crecer o aumentar; intransitivamente del crecimiento natural o espiritual, o causativamente cuando Dios concede el crecimiento');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0838', 'spa', 'crecimiento, aumento en tamaño o madurez', 'Sustantivo que denota crecimiento o aumento. Pablo describe el cuerpo de Cristo creciendo a través de lo que cada parte provee, haciendo ''crecimiento del cuerpo'' (Efesios 4:16; Colosenses 2:19). El término aparece en contextos botánicos en griego clásico para crecimiento físico de plantas o incrementos matemáticos. Pablo lo aplica metafóricamente al desarrollo de la iglesia hacia la madurez. El énfasis está en el aumento orgánico en lugar de la adición mecánica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0839', 'spa', 'mañana, el día siguiente — adverbio temporal que indica el día posterior al presente o a un punto de referencia en el tiempo', 'mañana, el día siguiente — adverbio temporal que indica el día posterior al presente o a un punto de referencia en el tiempo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0840', 'spa', 'áspero, severo, duro, austero', 'Adjetivo que significa áspero, severo o austero. Jesús cita a un siervo que temía a su amo como ''un hombre severo'' que cosecha donde no sembró (Lucas 19:21-22). El término deriva de una raíz que significa ''secarse'', y el uso clásico incluía vino áspero (opuesto a dulce), terreno accidentado o personalidades severas. Describe a alguien exigente y demandante, que no muestra indulgencia. Jesús lo usa para exponer la falsa percepción del siervo que llevó a la parálisis en lugar de la productividad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0841', 'spa', 'autosuficiencia, contentamiento, competencia, recursos adecuados', 'Sustantivo que denota autosuficiencia o contentamiento con lo que uno tiene. Pablo habla de Dios proveyendo suficiencia para que los creyentes abunden en buenas obras (2 Corintios 9:8). Elogia la piedad con contentamiento como gran ganancia (1 Timoteo 6:6). La filosofía clásica, especialmente el estoicismo, valoraba la autarkeia como el ideal de no necesitar nada externo. Pablo transforma esta virtud: el contentamiento cristiano no depende de recursos internos sino de la provisión de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0844', 'spa', 'por sí mismo, espontáneamente, automáticamente', 'Adjetivo que significa que actúa por sí mismo o espontáneo, frecuentemente usado de manera adverbial. Jesús describe la semilla brotando y creciendo automáticamente en Marcos 4:28: la tierra produce cosechas ''por sí misma''. En Hechos 12:10, la puerta de la prisión se abre ''por sí sola'' mientras Pedro es guiado por el ángel. El uso clásico incluía trípodes que se movían solos, puertas automáticas del Olimpo y plantas que crecían silvestres sin cultivo. El término enfatiza la acción sin agencia humana externa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0846', 'spa', 'Él/ella/eso (pronombre); mismo (adjetivo); mismo/en persona (intensivo) — la referencia de tercera persona multiuso', 'La palabra más versátil del griego para referencia de tercera persona, con tres funciones principales. Como pronombre personal simple equivale a ''él'', ''ella'', ''ello'' en todos los casos oblicuos. Como adjetivo atributivo (con artículo) significa ''el mismo'', ''idéntico''. Como pronombre intensivo (sin artículo) enfatiza identidad o contraste: ''él mismo'', ''en persona''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0847', 'spa', 'Aquí, allí; adverbio de lugar que indica el sitio exacto donde uno se encuentra o donde se le ha indicado permanecer.', 'Adverbio locativo que significa ''justo aquí'' o ''en este mismo lugar'', usado para anclar a alguien en una ubicación específica. Jesús dice a sus discípulos que ''se queden aquí'' (αὐτοῦ) mientras él va a orar en Getsemaní (Mt 26:36), y declara que algunos de los que están ''aquí'' no gustarán la muerte antes de ver el reino de Dios (Lc 9:27). En Hechos, marca lugares donde Pablo hizo pausa en sus viajes: Éfeso (Hch 18:19) o donde sus compañeros permanecieron (Hch 15:34; 21:4). El español distingue entre ''aquí'' y ''allí'', pero el término griego abarca ambos sentidos según el contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0848', 'spa', 'Pronombre reflexivo de tercera persona: a sí mismo, a sí misma, a sí mismos; ocasionalmente pronombre personal simple en el griego koiné', 'Pronombre reflexivo de tercera persona: a sí mismo, a sí misma, a sí mismos; ocasionalmente pronombre personal simple en el griego koiné');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0851', 'spa', 'Quitar, remover; cortar o cercenar — ya sea removiendo de manera abstracta (pecados, deshonra) o cercenando físicamente (una parte del cuerpo). ἀφαιρέ', 'Quitar, remover; cortar o cercenar — ya sea removiendo de manera abstracta (pecados, deshonra) o cercenando físicamente (una parte del cuerpo). ἀφαιρέω (aphaireō) abarca un amplio arco semántico que va desde la remoción abstracta hasta la amputación física violenta. Isabel alaba a Dios que ''quitó'' su deshonra (Lc 1:25), y Pablo declara que la sangre de toros y machos cabríos no puede ''quitar'' los pecados (Heb 10:4) — ambas son remociones abstractas de una condición o carga. Sin embargo, el mismo verbo describe a Pedro cortando la oreja del siervo del sumo sacerdote en Getsemaní (Mt 26:51; Mr 14:47; Lc 22:50), donde ''cortó'' reemplaza al más general ''quitar'' usado en contextos abstractos. Este cambio de remoción a cercenamiento marca una distinción genuina de sentido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0853', 'spa', 'Hacer invisible, desfigurar, destruir; causar que algo desaparezca, se deteriore o quede irreconocible.', 'Lleva en su raíz la idea de hacer algo invisible o irreconocible. En el Sermón del Monte, Jesús advierte que los hipócritas ''desfiguran'' sus rostros al ayunar (Mt 6:16), y que la polilla y el óxido ''destruyen'' los tesoros terrenales (Mt 6:19-20), dos aplicaciones vívidas del mismo verbo. En Hechos 13:41, Pablo cita la advertencia de Habacuc de que los burladores ''perecerán'' de asombro. Santiago 4:14 lo usa para la vida misma: un vapor que ''se desvanece''. El espectro semántico abarca desde la desfiguración hasta la aniquilación completa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0856', 'spa', 'letrina, retrete, lugar de defecación', 'Sustantivo que denota una letrina o retrete. Jesús enseña que la comida entra al estómago y sale a la letrina (Mateo 15:17; Marcos 7:19). El término deriva de ''hedra'' (asiento), con el prefijo sugiriendo un lugar apartado. Era una manera eufemística de referirse al retrete. Jesús lo usa al enseñar que las cosas externas no pueden contaminar ya que pasan por el sistema digestivo y son expulsadas, señalando que la contaminación moral viene del corazón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0859', 'spa', 'Liberación o soltura; en el NT principalmente el perdón o remisión de pecados, y ocasionalmente la liberación del cautiverio.', 'Liberación o soltura; en el NT principalmente el perdón o remisión de pecados, y ocasionalmente la liberación del cautiverio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0860', 'spa', 'ligamento, articulación, nexo que conecta partes del cuerpo', 'Sustantivo que denota un ligamento, articulación o conexión entre partes del cuerpo. Pablo lo usa metafóricamente dos veces para cómo el cuerpo de Cristo (la iglesia) se mantiene unido y crece mediante lo que cada ligamento suple (Efesios 4:16; Colosenses 2:19). El uso clásico incluía el sentido del tacto, agarre en lucha, contacto de superficies en matemáticas y arena para que los luchadores obtuvieran mejor agarre. El sentido anatómico de tejido conectivo se ajusta a la eclesiología corporal de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0861', 'spa', 'Incorrupción, inmortalidad; también integridad o pureza moral: ausencia de corrupción en el cuerpo o en el carácter.', 'Sustantivo que describe la cualidad de ser imperecedero, no alcanzado por la corrupción ni la muerte. Pablo lo emplea con gran fuerza en 1 Corintios 15 para representar el cuerpo de resurrección que reemplaza lo corruptible, y en Romanos 2:7 para designar la vida eterna que buscan quienes perseveran en hacer el bien. En 2 Timoteo 1:10 se dice que Cristo mismo sacó a la luz la inmortalidad mediante el evangelio. Un sentido ético secundario aparece en Tito 2:7, donde denota integridad o solidez en la enseñanza, una incorruptibilidad moral que refleja la física.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0862', 'spa', 'Imperecedero, incorruptible, inmortal; que no está sujeto a corrupción, muerte ni deterioro.', 'Formado con el prefijo privativo griego (ἀ-) y φθαρτός (perecedero, corruptible), este adjetivo describe lo que no puede ser destruido, corrompido ni morir. Pablo contrasta la corona perecedera del atleta con la corona ''imperecedera'' que los creyentes persiguen (1 Co 9:25) y proclama que los muertos serán resucitados ''incorruptibles'' (1 Co 15:52). Aplicado a Dios, señala que la naturaleza divina está completamente por encima de toda corrupción (Ro 1:23; 1 Ti 1:17). Pedro habla de una herencia ''incorruptible'' guardada en los cielos (1 P 1:4) y de una simiente ''incorruptible'' por la cual los creyentes son regenerados (1 P 1:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0863', 'spa', 'Despedir, soltar; dejar, abandonar; permitir; perdonar; descuidar; entregar el espíritu', 'Formado a partir de ἀπό (''lejos'') y ἵημι (''enviar''), ἀφίημι es uno de los verbos de mayor trascendencia teológica del Nuevo Testamento. Su campo semántico va desde el acto físico de dejar las redes para seguir a Jesús (Mt 4:20), pasando por el cotidiano ''dejar, permitir'' del trato social, hasta la profunda declaración ''tus pecados te son perdonados'' (Mt 9:2). La misma raíz que describe abandonar un lugar (Mt 23:38, ''vuestra casa os es dejada desierta'') también nombra el acto divino de liberar a un deudor de su obligación (Mt 18:27). El árabe distingue taraka (dejar) de ghafara (perdonar), revelando que el griego unifica bajo un solo verbo lo que muchas lenguas separan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0866', 'spa', 'no amante del dinero, libre del amor a la plata, sin codicia por las riquezas', 'Este raro adjetivo describe a una persona que no es esclava del amor al dinero o la plata. Aparece en dos contextos pastorales clave: como requisito para los supervisores de la iglesia y como exhortación general a los creyentes. El compuesto griego combina el prefijo negativo con ''philargyros'' (amante de la plata), creando un retrato vívido del contentamiento financiero. La evidencia multilingüe preserva la estructura literal ''no-amante-del-dinero'', enfatizando el rechazo deliberado del materialismo como rasgo de carácter esencial para el liderazgo espiritual y la vida cristiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0868', 'spa', 'Apartarse o retirarse de un lugar; caer en apostasía abandonando la fe; arrastrar a otros o incitar a la revuelta.', 'Apartarse o retirarse de un lugar; caer en apostasía abandonando la fe; arrastrar a otros o incitar a la revuelta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0869', 'spa', 'de repente, inesperadamente; lo que sucede sin previo aviso', 'Este adverbio significa de repente o inesperadamente, describiendo sucesos que ocurren sin previo aviso. En Pentecostés, «de repente» vino del cielo un sonido como de un viento recio (Hch 2:2). En la cárcel a medianoche, «de repente» hubo un gran terremoto que liberó a Pablo y Silas (Hch 16:26). Los habitantes de Malta esperaban que Pablo se hinchase o cayese muerto por la mordedura de una víbora, pero al ver que no le pasaba nada tras largo rato, cambiaron «de repente» de opinión (Hch 28:6). La palabra subraya la naturaleza inmediata e inesperada de la intervención divina o de los sucesos dramáticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0870', 'spa', 'sin temor, intrépidamente, con audacia; actuando con valentía o, negativamente, con impudencia temeraria', 'El adverbio ἀφόβως («sin temor») aparece tanto en sentido positivo como negativo en sus cuatro ocurrencias neotestamentarias. La profecía de Zacarías celebra servir a Dios «sin temor» todos los días de la vida (Lucas 1:74), una bendita libertad del terror. Pablo espera que Timoteo ministre en Corinto «sin temor» (1 Corintios 16:10), y los creyentes filipenses anuncian la palabra «intrépidamente» gracias al encarcelamiento de Pablo (Filipenses 1:14). Judas 1:12, sin embargo, oscurece el sentido: los falsos maestros participan «sin temor» en los ágapes, y su desvergüenza es señal de corrupción espiritual más que de santa audacia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0872', 'spa', 'apartar la mirada de todo lo demás y fijar la vista en, mirar atentamente, tener a la vista', 'Este verbo captura el acto enfocado de apartar la mirada de las distracciones hacia un solo objeto o persona. El rango clásico incluye ver objetos distantes, mirar hacia una meta y fijar la atención con propósito. En el Nuevo Testamento aparece dos veces con profundo significado teológico: Pablo habla de ''apartar la mirada hacia'' la situación de Timoteo (Fil 2:23), y Hebreos exhorta a los creyentes a apartar la mirada de todo lo demás hacia Jesús (Heb 12:2). La evidencia multilingüe se divide entre ''ver'' y ''mirar atentamente'', con las lenguas romances y germánicas enfatizando la naturaleza dirigida y enfocada de la mirada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0873', 'spa', 'Apartar, separar; delimitar con fronteras; consagrar para el servicio divino; excluir, marginar. Formado de ἀπό (''lejos de'') y ὁρίζω (''definir, poner ', 'Apartar, separar; delimitar con fronteras; consagrar para el servicio divino; excluir, marginar. Formado de ἀπό (''lejos de'') y ὁρίζω (''definir, poner un límite''), este verbo porta la idea fundamental de trazar una línea divisoria. Jesús lo usa para la separación escatológica de ovejas y cabras (Mt 25:32) y de trigo y cizaña (Mt 13:49), mientras que Pablo lo reclama para su propio llamado apostólico: ''apartado para el evangelio de Dios'' (Ro 1:1; cf. Gá 1:15). El español ''apartar'' y ''separar'' preservan fielmente tanto la dimensión física como la teológica. El lado más oscuro aparece en Gálatas 2:12, donde Pedro ''se apartaba'' de la comunión de mesa con los gentiles, y en Lucas 6:22, donde Jesús advierte que la gente ''apartará'' a sus seguidores. Desde la consagración sagrada hasta el ostracismo social, la palabra gira en torno a quién traza el límite y por qué.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0874', 'spa', 'Ocasión, oportunidad o base de operaciones; un punto de partida que posibilita o provoca una acción.', 'Designa un punto de partida o asidero desde el cual procede una acción ulterior. En el griego clásico se refería a una base militar de operaciones, pero en el Nuevo Testamento adquiere un sentido moral y relacional: el asidero que el pecado aprovecha mediante el mandamiento (Rom 7:8, 11), o la ocasión para jactarse o criticar en disputas comunitarias (2 Cor 5:12; 11:12). Español ''ocasión'', francés ''occasion'' y alemán ''Anlass'' conservan la noción de una oportunidad desencadenante más que un mero momento en el tiempo. El uso reiterado de Pablo en Romanos 7 personifica vívidamente al pecado como un adversario que toma posición estratégica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0875', 'spa', 'echar espuma, espumar por la boca, producir espuma o espumarajos', 'Este verbo describe vívidamente el acto físico de espumar, con uso clásico que va desde copas de vino hasta bocas humanas y animales. En el Nuevo Testamento, ambas ocurrencias aparecen en el relato de Marcos del muchacho endemoniado, creando un retrato físico descarnado de aflicción espiritual. El muchacho echa espumarajos por la boca como parte de las convulsiones violentas causadas por el espíritu inmundo. El español ''echa espumarajos'' captura la naturaleza violenta e involuntaria del espumar, mientras que el francés ''écumer'' y el alemán ''schäumen'' preservan el significado básico entre idiomas. Este detalle gráfico enfatiza la severidad de la opresión demoníaca y la totalidad de la sanidad de Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0877', 'spa', 'insensatez, necedad; falta de entendimiento o juicio prudente; conducta o discurso contrario a la sabiduría', 'Derivado de ἄφρων (''sin juicio, insensato''), ἀφροσύνη designa una carencia de entendimiento o juicio prudente. En Marcos 7:22, Jesús la incluye entre los males que brotan del corazón humano: la insensatez como fallo moral y espiritual, no meramente intelectual. El uso paulino en 2 Corintios 11 es marcadamente irónico: Pablo pide repetidamente a los corintios que soporten su ''insensatez'' (11:1, 17, 21) al lanzar lo que los eruditos llaman el ''discurso del necio'', jactándose de sus credenciales apostólicas. La palabra queda así coloreada por su opuesto, σοφία: nombra lo que sucede cuando la sabiduría está ausente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0878', 'spa', 'Insensato, necio — carente de entendimiento moral y espiritual; que actúa sin consideración hacia Dios ni hacia la sabiduría. El adjetivo ἄφρων (aphrō', 'Insensato, necio — carente de entendimiento moral y espiritual; que actúa sin consideración hacia Dios ni hacia la sabiduría. El adjetivo ἄφρων (aphrōn) describe a alguien privado de entendimiento — no tanto deficiente intelectualmente como moral y espiritualmente insensato. Dios se dirige al hombre rico que acumula grano con el veredicto demoledor: ''¡Necio! Esta noche vienen a pedirte tu alma'' (Lc 12:20). Jesús pregunta a los fariseos: ''¿El que hizo lo de fuera, no hizo también lo de dentro?'' (Lc 11:40), exponiendo su necedad. Pablo lo usa con mordaz ironía en 2 Corintios 11:16-19 y 12:6, 11, donde adopta la persona de un ''necio'' para avergonzar a sus oponentes. En 1 Corintios 15:36 reprende a los que dudan de la resurrección. Romanos 2:20 nota irónicamente que el judío se ve a sí mismo como ''instructor de los insensatos''. El español ''insensato/necio'' captura plenamente la dimensión moral-espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0880', 'spa', 'sin voz, mudo, silencioso; incapaz de hablar o que no produce sonido inteligible', 'Compuesto del alfa privativa y φωνή (''voz, sonido''), ἄφωνος describe lo que carece de voz o de la facultad del habla. El NT lo emplea en un abanico llamativo de sujetos. Hechos 8:32 cita Isaías 53:7, comparando a Cristo con un cordero ''mudo'' ante su trasquilador. Pablo lo aplica a los ídolos mudos que los corintios adoraban (1 Co 12:2) y a instrumentos musicales que no producen sonido distinguible (1 Co 14:10). Segunda Pedro 2:16 ofrece el uso más vívido: la burra de Balaam, ''bestia de carga sin voz'', reprende al profeta con voz humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0881', 'spa', 'Acaz, rey de Judá, hijo de Jotam, padre de Ezequías', 'Este nombre propio, transliterado del hebreo אָחָז (''él ha agarrado''), identifica al duodécimo rey de Judá que reinó durante el siglo octavo a.C. tardío. Acaz es recordado en las Escrituras principalmente por su idolatría y su apelación a Asiria por ayuda militar en lugar de confiar en el Señor. En la genealogía de Jesús en Mateo, Acaz aparece dos veces en el versículo 1:9, siguiendo el patrón donde la genealogía menciona tanto ''Jotam engendró a Acaz'' como ''Acaz engendró a Ezequías''. El nombre aparece idéntico en las traducciones al inglés, español, francés y alemán, reflejando las prácticas estándar de transliteración para nombres propios bíblicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0882', 'spa', 'Acaya, la provincia senatorial romana que comprendía el sur de Grecia con su capital en Corinto. Nombre propio de la provincia romana que abarcaba el ', 'Acaya, la provincia senatorial romana que comprendía el sur de Grecia con su capital en Corinto. Nombre propio de la provincia romana que abarcaba el sur de Grecia, incluyendo el Peloponeso y la región alrededor de Atenas. Su capital era Corinto, donde Pablo compareció ante el procónsul Galión (Hch 18:12, 27; 19:21). En las cartas de Pablo, Acaya designa a la comunidad más amplia de creyentes en el sur de Grecia, frecuentemente emparejada con Macedonia para representar a toda la iglesia griega (Ro 15:26; 1 Co 16:15; 2 Co 1:1; 9:2; 11:10; 1 Ts 1:7-8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0884', 'spa', 'ingrato, desagradecido, sin gratitud ni apreciación', 'Este adjetivo describe a personas que carecen de gratitud o no muestran agradecimiento. El griego clásico lo usaba para personas desagradables o poco gratas, o tareas poco gratificantes, pero en el Nuevo Testamento se enfoca específicamente en la falta moral de ingratitud. Jesús lo usa para describir cómo Dios muestra bondad incluso a los ''ingratos y malos'' (Luc 6:35), mientras que Pablo lo lista entre los vicios que caracterizan a la gente en los últimos días (2 Tim 3:2). La palabra combina el prefijo negativo con ''charis'' (gracia/favor), sugiriendo a alguien inmune a la gracia o no dispuesto a reconocer los dones recibidos. Todos los idiomas lo traducen directamente como ''ingrato'', mostrando reconocimiento universal de este vicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0885', 'spa', 'Aquim, un antepasado de Jesús en la genealogía de Mateo', 'Este nombre propio aparece únicamente en la genealogía de Jesús en Mateo, identificando a un ancestro postexílico en la línea desde Zorobabel hasta Jesús. A diferencia de muchos nombres genealógicos extraídos del Antiguo Testamento, Aquim no aparece en las Escrituras hebreas, por lo que lo conocemos solo a través del relato de Mateo. El nombre podría derivar de una forma abreviada de Joaquín o Jeconías, aunque su etimología exacta permanece incierta. Ambas menciones en Mateo 1:14 siguen el patrón genealógico: ''Azor engendró a Aquim, y Aquim engendró a Eliud''. El nombre mantiene una ortografía casi idéntica entre idiomas (español Aquim, francés/alemán Achim), reflejando la transliteración estándar de esta figura por lo demás desconocida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0886', 'spa', 'no hecho con manos, no de construcción humana; hecho espiritual o divinamente', 'Este adjetivo compuesto describe aquello que no ha sido hecho por manos humanas. En el juicio de Jesús, falsos testigos afirmaron que él había dicho que destruiría el templo «hecho con manos» y edificaría otro «no hecho con manos» en tres días (Mr 14:58). Pablo contrasta las tiendas terrenales con el edificio de Dios, eterno en los cielos, «no hecho de manos» (2 Co 5:1). Colosenses 2:11 habla de una circuncisión «no hecha con manos», el despojamiento espiritual de la carne en Cristo. El término distingue la obra humana de la realidad divina o espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0887', 'spa', 'niebla, neblina espesa, bruma que oscurece, oscuridad sobre los ojos', 'Este sustantivo describe niebla o neblina, con el griego clásico usándolo especialmente para la niebla que cubre los ojos moribundos o ciega a alguien mediante acción divina. Homero lo usa para la oscuridad que cae sobre los ojos en la muerte o cuando un dios quita la capacidad de ver a alguien. En las dos apariciones del Nuevo Testamento, lleva este sentido de niebla cegadora: el mago Elimas es golpeado con ''niebla y oscuridad'' cayendo sobre sus ojos (Hechos 13:11), y los falsos maestros son comparados con ''nieblas impulsadas por la tormenta'' (2 Pedro 2:17). La palabra aparece en forma plural en ambos pasajes, enfatizando ya sea múltiples episodios o la cualidad completamente oscurecedora de la oscuridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0888', 'spa', 'inútil, no rentable, sin valor, no apto para el servicio, que no sirve para nada', 'Este adjetivo denota algo o alguien inútil o no rentable, incapaz de cumplir su propósito previsto. El griego clásico lo aplicaba a cualquier cosa, desde guerreros no aptos hasta tareas improductivas, con la idea central de no proporcionar beneficio o servicio. En el Nuevo Testamento, Jesús lo usa en la parábola de los talentos para el ''siervo inútil'' que enterró el dinero de su amo (Mateo 25:30), mientras Lucas registra a Jesús enseñando que incluso los siervos fieles deben considerarse ''inútiles'' después de cumplir su deber (Lucas 17:10). La palabra combina el prefijo negativo con una raíz relacionada con uso o servicio, creando el sentido de ''no apto para el uso''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0891', 'spa', 'Hasta, hasta que — conjunción y preposición temporal y espacial que marca el punto final de una acción o extensión', 'Ἄχρι (también ἄχρις) funciona como preposición y conjunción, marcando el límite terminal de un período o extensión. Sus 49 ocurrencias se reparten entre usos temporales y espaciales. Temporalmente, rige expresiones como «hasta el día» (Lc 1:20; Hch 1:2) y marcadores paulinos de historia salvífica: «hasta que haya entrado la plenitud de los gentiles» (Ro 11:25). En Apocalipsis puntúa umbrales escatológicos (Ap 20:3, 5). Espacialmente significa «hasta» un lugar (Hch 13:6). El español «hasta», el francés jusqu''a y el alemán bis captan su sentido limitativo de punto final.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0892', 'spa', 'paja, cascarilla, tamo dejado después de la trilla, la parte sin valor separada del grano', 'Este sustantivo se refiere a la paja seca y ligera separada del grano durante el proceso de trilla y aventado. En la práctica agrícola, después de que el grano era golpeado para separar los granos de los tallos, la mezcla era lanzada al aire para que el viento soplara la paja inútil mientras el grano más pesado caía de vuelta a la era. Ambas apariciones en el Nuevo Testamento están en la predicación de Juan el Bautista, donde usa esta vívida imagen agrícola para describir el juicio divino. El Mesías aventará completamente su era, recogiendo el trigo en el granero pero quemando la paja ''con fuego que nunca se apagará'' (Mateo 3:12; Lucas 3:17). Esta imagen de separación y destrucción permanente habría sido inmediatamente clara para una audiencia agrícola.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0894', 'spa', 'ajenjo, una hierba amarga, Artemisia absinthium, usada como símbolo de amargura y calamidad', 'Este sustantivo nombra la planta de ajenjo (Artemisia absinthium), conocida en todo el mundo antiguo por su sabor intensamente amargo. El Antiguo Testamento usa frecuentemente el ajenjo como símbolo de juicio amargo, y esta imagen continúa en Apocalipsis. Ambas apariciones en el Nuevo Testamento están en Apocalipsis 8:11, donde una gran estrella llamada ''Ajenjo'' cae del cielo y hace que la tercera parte de las aguas se vuelvan amargas, causando muchas muertes. La personificación de la amargura como un agente de juicio cósmico muestra cuán profundamente el carácter amargo de esta planta se imprimió en la imaginación bíblica. Notablemente, el nombre aparece tanto como nombre propio para la estrella como descripción de la cualidad amarga de las aguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0897', 'spa', 'Babilonia — la antigua ciudad y el imperio mesopotámico; usada históricamente para el exilio y simbólicamente para Roma en Apocalipsis', 'Babilonia — la antigua ciudad y el imperio mesopotámico; usada históricamente para el exilio y simbólicamente para Roma en Apocalipsis');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0899', 'spa', 'Profundidad o lugar profundo, ya sea físico (mar, tierra) o metafórico (de la sabiduría, riquezas o realidad espiritual divina).', 'El sustantivo βάθος abarca tanto la profundidad literal como la figurada. En las parábolas del sembrador, la semilla cae en terreno pedregoso sin ''profundidad'' de tierra (Mt 13:5; Mc 4:5). Jesús instruye a Simón a adentrarse en lo ''profundo'' para pescar (Lc 5:4). Pero Pablo eleva el término a alturas teológicas: ni la altura ni la ''profundidad'' pueden separarnos del amor de Dios (Ro 8:39), y exclama ante la ''profundidad'' de las riquezas de la sabiduría divina (Ro 11:33). Apocalipsis habla de las ''cosas profundas'' de Satanás (Ap 2:24). En Efesios 3:18, Pablo ora para que los creyentes comprendan la anchura, la longitud, la altura y la ''profundidad'' del amor de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0901', 'spa', 'profundo, hondo; físicamente profundo o que ocurre en la madrugada (''alba profunda''), y figuradamente de misterios ocultos', 'El adjetivo βαθύς abarca profundidad física, hora temprana y hondura figurada en sus cuatro apariciones neotestamentarias. Juan 4:11 es literal: la samaritana dice a Jesús que ''el pozo es profundo''. Lucas 24:1 emplea la expresión distintiva ''alba profunda'' (ὄρθρου βαθέος) para las horas más tempranas de la mañana de Resurrección. Hechos 20:9 describe a Eutico cayendo en ''sueño profundo'' durante el largo sermón de Pablo. Apocalipsis 2:24 habla de ''las profundidades de Satanás'', frase que Jesús usa irónicamente contra las pretensiones de falsos maestros en Tiatira.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0903', 'spa', 'Balaam, profeta pagano contratado para maldecir a Israel, quien terminó bendiciéndolo', 'Este nombre propio designa a Balaam, el profeta no israelita de Números 22-24, contratado para maldecir a Israel pero que terminó bendiciéndolo. Pedro lo presenta como ejemplo de quien amó el salario de la injusticia (2 Pe 2:15). Judas condena a quienes se precipitaron en el «error de Balaam» por lucro (Jud 11). Apocalipsis advierte contra «la doctrina de Balaam», quien enseñó a Balac a poner tropiezos ante Israel (Ap 2:14). Balaam se convierte así en prototipo del falso maestro motivado por la codicia que arrastra al pueblo de Dios al pecado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0905', 'spa', 'Bolsa o monedero usado para llevar monedas', 'En el mundo mediterráneo antiguo, el βαλλάντιον era una bolsa de cuero o monedero empleado para transportar dinero. Jesús hace referencia a este objeto dos veces en el Evangelio de Lucas: primero prohibiendo a los setenta discípulos llevar uno en su misión (Lucas 10:4), y luego revirtiendo esa instrucción en la Última Cena (Lucas 22:36). En Lucas 12:33, exhorta a vender las posesiones para obtener ''bolsas que no se desgastan'', una metáfora notable del tesoro celestial. Tanto el español ''bolsa'' como el francés ''bourse'' capturan este accesorio financiero cotidiano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0906', 'spa', 'Arrojar, echar, lanzar; poner o depositar; en pasiva: ser arrojado; también yacer postrado, derramar o azotar', 'Un verbo extraordinariamente versátil de propulsión y colocación que impregna los Evangelios y el Apocalipsis. En su registro más violento describe el acto de arrojar — al fuego, al mar, a la gehena — cargando el peso del juicio divino a lo largo de las imágenes apocalípticas de Apocalipsis. Sin embargo, el mismo vocablo sirve discretamente para depositar dinero en el arca del templo (Mc 12:41–44) o echar vino en odres (Mt 9:17). El español distingue arrojar (lanzar con fuerza) de echar (poner/depositar), mientras que el árabe emplea tanto طَرَحَ (arrojar con violencia) como وَضَعَ (colocar), revelando la amplitud semántica que un solo verbo griego abarca. Las formas pasivas son especialmente prominentes en contextos de juicio, donde ''ser arrojado'' a las tinieblas exteriores o al lago de fuego se convierte en imagen recurrente de condena escatológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0907', 'spa', 'Bautizar o ser bautizado; sumergir en agua como rito de arrepentimiento, identificación o purificación', 'El verbo que dio al cristianismo uno de sus sacramentos definitorios, derivado de βάπτω («sumergir»). En el Nuevo Testamento abarca tres usos distintos: recibir el bautismo como converso o penitente (Mt 3:6, 13-16; Hch 2:41), administrar el bautismo como lo hicieron Juan o los apóstoles (Mt 3:11; 28:19; Mr 1:4), y el sentido helenístico más amplio de lavamiento ritual no vinculado a la iniciación cristiana (Mr 7:4; Lc 11:38). La evidencia multilingüe es notable: el español «bautizar», el francés baptiser y el alemán taufen derivan de la raíz griega o la calcan, testimoniando cuán profundamente esta palabra moldeó el vocabulario religioso occidental.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0908', 'spa', 'Bautismo; el rito de inmersion en agua que significa arrepentimiento o union con la muerte y resurreccion de Cristo.', 'Bautismo; el rito de inmersion en agua que significa arrepentimiento o union con la muerte y resurreccion de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0909', 'spa', 'Lavamiento, inmersión, bautismo; purificación ceremonial o ritual mediante agua, desde ritos judíos de purificación hasta el bautismo cristiano.', 'Se refiere al acto de sumergir o lavar con agua, abarcando tanto las abluciones ceremoniales judías como el bautismo propiamente cristiano. En Marcos 7:4, 8 describe los ritos tradicionales de purificación de los fariseos —lavamiento de vasos, jarras y utensilios—, mientras que Hebreos 9:10 se refiere igualmente a las ''abluciones'' del Antiguo Pacto. Colosenses 2:12 y Hebreos 6:2 aplican el término al bautismo cristiano como doctrina fundamental. El rango semántico se extiende desde el lavamiento ritual genérico hasta el sacramento cristiano específico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0910', 'spa', 'Bautista, Bautizador — título aplicado exclusivamente a Juan hijo de Zacarías, el precursor que bautizaba en el Jordán', 'Bautista, Bautizador — título aplicado exclusivamente a Juan hijo de Zacarías, el precursor que bautizaba en el Jordán');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0911', 'spa', 'Mojar o sumergir algo en un líquido; teñir mediante inmersión', 'El verbo βάπτω denota el acto físico de mojar o sumergir algo en un líquido, a diferencia de βαπτίζω, que adquirió el sentido ritual especializado. En Juan 13:26, Jesús moja un bocado en el plato durante la Última Cena para identificar a su traidor. El hombre rico en el Hades ruega a Lázaro que moje la punta de su dedo en agua (Lucas 16:24). En Apocalipsis 19:13, el manto de Cristo se describe como ''teñido en sangre''. El español distingue ''mojar'' (humedecer) y ''teñir'' (dar color), capturando ambas dimensiones de esta palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0912', 'spa', 'Barrabás — el prisionero insurrecto que la multitud eligió liberar en lugar de Jesús durante la Pascua. Βαραββᾶς (Barabbás), del arameo bar-Abba (''hij', 'Barrabás — el prisionero insurrecto que la multitud eligió liberar en lugar de Jesús durante la Pascua. Βαραββᾶς (Barabbás), del arameo bar-Abba (''hijo del padre''), es el prisionero liberado por Pilato en lugar de Jesús según la costumbre pascual de liberar a un preso. Marcos y Lucas lo identifican como alguien que había cometido un homicidio durante una insurrección (Mr 15:7; Lc 23:19, 25); Mateo lo llama un ''preso notable'' (Mt 27:16); Juan simplemente lo denomina un ''ladrón'' (Jn 18:40). La ironía narrativa es profunda: la multitud exige la libertad de un hombre violento mientras condena al inocente Hijo del Padre. Algunos manuscritos tempranos de Mateo 27:16-17 dan su nombre completo como ''Jesús Barrabás'', intensificando el contraste dramático.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0915', 'spa', 'Extranjero, persona que no habla griego; cualquiera ajeno a la identidad lingüística y cultural grecorromana.', 'βάρβαρος imitaba originalmente el sonido del habla incomprensible —''bar-bar''— y designaba a cualquiera que no hablara griego. En el Nuevo Testamento el término aparece sin la connotación peyorativa moderna de ''bárbaro''. Los nativos malteses son llamados βάρβαροι simplemente porque no hablaban ni griego ni latín (Hch 28:2, 4), y Pablo empareja ''griegos y bárbaros'' como un merismo abarcador de toda la humanidad (Rom 1:14). En 1 Cor 14:11, Pablo lo usa de manera incisiva: si no puedes entender la lengua que se habla, hablante y oyente son ''extranjeros'' el uno para el otro. La palabra así ilumina la realidad multilingüe e intercultural de la iglesia primitiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0916', 'spa', 'Agobiar, cargar o abrumar; usado en voz pasiva para indicar pesadez por sueño, aflicción o dificultad.', 'βαρέω significa hacer pesado o agobiar, y en el Nuevo Testamento aparece casi exclusivamente en voz pasiva, describiendo la experiencia de ser abrumado u oprimido. Los ojos de los discípulos ''estaban cargados'' de sueño en Getsemaní (Mt 26:43; Lc 9:32), Jesús advierte contra corazones ''agobiados'' por la disipación (Lc 21:34), y Pablo describe haber sido ''abrumado sobremanera, más allá de nuestras fuerzas'' en Asia (2 Cor 1:8) y gemir bajo el peso de la mortalidad (2 Cor 5:4). El verbo capta una pesadez sentida —física, emocional o espiritual— que presiona sobre la persona entera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0917', 'spa', 'pesadamente, con dificultad, torpemente, de manera lenta o endurecida', 'Este adverbio describe una manera pesada, dificultosa o lenta de actuar, derivado del verbo que significa cargar o agobiar. En sus dos apariciones en el Nuevo Testamento, modifica el oír: las personas oyen ''pesadamente'' o ''con oídos torpes'', incapaces de comprender verdaderamente porque sus facultades sensoriales y mentales se han vuelto lentas. Mateo 13:15 y Hechos 28:27 citan ambos Isaías 6:9-10, donde Dios describe un pueblo cuyos oídos se han vuelto torpes y pesados. No se trata de sordera física sino de una incapacidad endurecida y voluntaria para verdaderamente oír y responder a la palabra de Dios. La palabra sugiere peso, carga y la dificultad de percepción cuando los corazones resisten la verdad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0918', 'spa', 'Bartolomé, uno de los doce apóstoles; del arameo ''hijo de Tolmai''', 'Bartolomé es uno de los doce apóstoles de Jesús, mencionado en las cuatro listas canónicas de los Doce (Matt 10:3; Mark 3:18; Luke 6:14; Acts 1:13). Su nombre proviene del arameo bar-Talmay, que significa ''hijo de Tolmai'', un patronímico más que un nombre personal, lo cual ha llevado a muchos estudiosos desde el siglo IX a identificarlo con Natanael del Evangelio de Juan. Las diversas lenguas conservan formas cercanas al griego Βαρθολομαῖος.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0921', 'spa', 'Bernabe -- Jose el levita de Chipre, apodado ''hijo de consolacion,'' companero misionero inicial de Pablo.', 'Bernabe -- Jose el levita de Chipre, apodado ''hijo de consolacion,'' companero misionero inicial de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0922', 'spa', 'Carga, peso o gravamen; usado literalmente del trabajo pesado y figuradamente de gravedad moral, autoridad u obligación espiritual.', 'βάρος denota peso o pesadez tanto en sentido físico como figurado. Jesús lo emplea para referirse a la ''carga y el calor del día'' soportados por los jornaleros en la viña (Mt 20:12), mientras que el concilio de Jerusalén resuelve no imponer mayor ''carga'' de lo necesario a los creyentes gentiles (Hch 15:28). Pablo contrasta la ''leve tribulación momentánea'' con un ''eterno peso de gloria'' (2 Cor 4:17) —una notable inversión metafórica donde βάρος se convierte en algo deseable. También exhorta a sobrellevar las cargas mutuamente (Gál 6:2) y alude al derecho apostólico de reclamar ''peso'' o autoridad (1 Tes 2:6). El español distingue útilmente entre ''carga'' y ''peso'', reflejando el doble registro de la palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0923', 'spa', 'Barsabás, sobrenombre que significa ''hijo de Sabá'', llevado por dos hombres diferentes en Hechos', 'Este sobrenombre, derivado del arameo que significa ''hijo de Sabá'' o ''hijo del sábado'', identifica a dos hombres diferentes en el libro de Hechos. Primero, José llamado Barsabás (también apellidado Justo) fue uno de los dos candidatos para reemplazar a Judas entre los doce apóstoles, aunque la suerte cayó sobre Matías (Hechos 1:23). Segundo, Judas llamado Barsabás fue un líder entre los creyentes de Jerusalén, elegido con Silas para acompañar a Pablo y Bernabé a Antioquía con el decreto apostólico (Hechos 15:22). El sobrenombre compartido sugiere un apellido familiar común o posiblemente indica nacimiento en sábado, aunque los dos hombres parecen ser individuos no relacionados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0925', 'spa', 'cargar, abrumar, oprimir; hacer pesado o fatigar', 'Verbo derivado del adjetivo βαρύς (''pesado'') que describe la acción de cargar algo o hacerlo pesado. En su uso físico se aplica a vestiduras que pesan sobre alguien o a miembros del cuerpo entorpecidos por la fatiga. La voz pasiva aparece con frecuencia: estar abrumado, tener los miembros pesados o la mano inutilizada. En sentido figurado incluye estar oprimido por la sed, el exceso o diversas cargas. Un uso médico especializado describe el estado de embarazo. El término abarca tanto el peso físico literal como las cargas metafóricas que oprimen o agotan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0926', 'spa', 'Pesado, gravoso, de peso; describe peso físico, exigencias opresivas, gravedad moral o severidad feroz.', 'Barys, el adjetivo del que deriva el sustantivo baros, abarca un amplio arco semántico que va desde la pesadez literal hasta la severidad figurada. Jesús denuncia a los fariseos por imponer cargas «pesadas» a los demás (Mt 23:4) y por descuidar los asuntos «más importantes» de la ley: la justicia, la misericordia y la fidelidad (Mt 23:23). Pablo habla de la impresión «de peso» que causan sus cartas frente a su débil presencia corporal (2 Co 10:10). Lucas describe a los lobos «feroces» que devastarán el rebaño (Hch 20:29) y los cargos «graves» presentados contra Pablo (Hch 25:7). Su alcance —del peso físico a la gravedad moral y la ferocidad amenazante— resulta notablemente coherente en las distintas lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0928', 'spa', 'Atormentar, torturar, causar sufrimiento intenso; ser azotado o sacudido por las olas', 'Atormentar, torturar, causar sufrimiento intenso; ser azotado o sacudido por las olas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0929', 'spa', 'Tormento, tortura, angustia; la imposición o experiencia de dolor intenso como castigo.', 'Designa el acto o estado de ser torturado: un dolor intenso infligido deliberadamente como castigo o experimentado como juicio divino. Las seis apariciones en el Nuevo Testamento se encuentran en Apocalipsis, donde la palabra describe las consecuencias agonízantes de la ira de Dios sobre los impenitentes. Las langostas semejantes a escorpiones de la quinta trompeta infligen tormento durante cinco meses (Ap 9:5), mientras que el humo del tormento de los idólatras asciende por siempre (Ap 14:11). La autocomplacencia lujosa de Babilonia es retribuida con igual medida de tormento (Ap 18:7, 10). El término se centra en la idea de sufrimiento atroz de carácter punitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0931', 'spa', 'Tormento, tortura, sufrimiento intenso o angustia severa', 'Este sustantivo designa tormento, tortura o sufrimiento severo. Mateo resume el ministerio sanador de Jesús incluyendo a quienes padecían diversas enfermedades y «tormentos» (Mt 4:24). El hombre rico en el Hades clama que sufre en «este tormento» (Lc 16:23, 28). Originalmente el término se refería a la piedra de toque para verificar la pureza del oro; luego pasó a significar la tortura aplicada al interrogar esclavos y, más ampliamente, cualquier aflicción severa. En el NT describe tanto padecimientos físicos como angustia escatológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0932', 'spa', 'Reino, reinado, dominio real; el gobierno soberano de un rey y el ámbito donde ese gobierno se ejerce', 'Βασιλεία se sitúa en el centro mismo de la proclamación de Jesús: ''El reino de los cielos se ha acercado'' (Mt 4:17). Denota tanto el acto dinámico del reinar de Dios como la esfera en la que ese reinado se experimenta. Solo en los Evangelios sinópticos, la expresión ''reino de Dios/de los cielos'' aparece más de 80 veces, haciendo de βασιλεία posiblemente el sustantivo con mayor carga teológica del Nuevo Testamento. Su campo semántico — desde la autoridad real hasta el dominio territorial y la esperanza escatológica — se capta consistentemente en todas las lenguas: ''reino'', ''royaume'', ''Reich'', ''kerajaan''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0933', 'spa', 'palacio real, morada regia; tesoro real; capital del reino; tiara o diadema', 'Sustantivo neutro que designa elementos asociados a la realeza, principalmente la morada o palacio real. La forma plural ''palacios reales'' aparece con frecuencia en textos clásicos. Por extensión puede referirse a la sede del imperio, la ciudad capital donde reside el poder regio. Otro sentido identifica el tesoro real, donde se guarda la riqueza del rey. También adquiere el significado concreto de insignia real: la tiara o diadema portada como símbolo de la realeza, que aparece en referencias de la Septuaginta como ''diadema de hermosura''. Usos botánicos nombran ciertas plantas, posiblemente por su apariencia o asociaciones regias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0934', 'spa', 'real, regio, perteneciente a un rey, digno de un rey', 'Este adjetivo significa real o regio, describiendo lo que pertenece a un rey o es digno de él. El griego clásico lo aplicaba a casas reales, poder y artículos selectos considerados dignos de la realeza. En el Nuevo Testamento, aparece en dos contextos contrastantes: Jesús habla de aquellos en vestiduras delicadas que moran ''en las casas de los reyes'' o ''palacios'' (Lucas 7:25), mientras Pedro llama a los creyentes ''un sacerdocio real'' (1 Pedro 2:9). La palabra conlleva connotaciones de excelencia, autoridad y estatus especial asociado con la realeza. El uso de Primera de Pedro transforma esta categoría mundana en realidad espiritual: los creyentes colectivamente forman un sacerdocio con dignidad y privilegio real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0935', 'spa', 'Rey, gobernante, soberano; usado para monarcas terrenales, el Mesías y Dios como gobernante supremo', 'Βασιλεύς designa a un rey o soberano que ejerce autoridad suprema sobre un pueblo o territorio. En el Nuevo Testamento se aplica a gobernantes históricos como Herodes (Mt 2:1), al César como emperador romano y, de manera suprema, a Jesús como el rey davídico prometido y a Dios como Rey eterno. Las traducciones multilingües lo vierten uniformemente con equivalentes directos — español ''rey'', francés ''roi'', alemán ''König'' — reflejando el concepto universalmente comprendido de autoridad monárquica. El vocablo porta peso tanto político como teológico, especialmente en la expresión ''Rey de reyes'' (Ap 19:16).');